// This file is task 013's `,` settings full-screen takeover skeleton (SPEC
// §11.5): a category list on the left, the selected category's field list
// on the right, both generated by walking internal/config.Schema rather
// than a second, hand-written field set (the exact defect requirement 22
// exists to catch). Navigation beyond "open, close" (tab/left/right/up/
// down, `/` fuzzy search), per-kind rendering, save/discard and the env-
// override label are tasks 014-018; this file only lays the frame down and
// proves it walks the schema and stays inside the terminal's budget.

// settingsCategory groups the schema fields that share one Field.Section
// under one human category name for the takeover's left-hand list.
type settingsCategory struct {
	Name    string
	Section string
	Fields  []config.Field
}

// settingsCategoryName maps a schema Field.Section to the takeover's
// human category label. Recorded here (rather than left to whichever task
// first needed a name) since task 013's notes flagged this as a decision
// to make and record: "" (config.toml's own top level) is "General", "ui"
// is "UI", "env" is "Environment" — matching config.toml's own section
// names for anything not top-level, since that is what a user editing the
// file by hand already sees.
func settingsCategoryName(section string) string {
	switch section {
	case "":
		return "General"
	case "ui":
		return "UI"
	case "env":
		return "Environment"
	case "notify":
		return "Notify"
	default:
		return strings.ToUpper(section[:1]) + section[1:]
	}
}

// settingsCategories walks config.Schema exactly once, grouping fields by
// Section in the order each section is first seen (schema.go already lists
// "", then "ui", then "env" contiguously, but this does not assume that —
// a schema field reordered or a new section inserted between others still
// groups correctly). This is the one and only place tasks 013-018 read the
// schema to build the takeover's category/field lists: neither list is
// ever hand-written alongside it.
func settingsCategories() []settingsCategory {
	var categories []settingsCategory
	indexBySection := map[string]int{}
	for _, field := range config.Schema {
		i, ok := indexBySection[field.Section]
		if !ok {
			i = len(categories)
			indexBySection[field.Section] = i
			categories = append(categories, settingsCategory{
				Name:    settingsCategoryName(field.Section),
				Section: field.Section,
			})
		}
		categories[i].Fields = append(categories[i].Fields, field)
	}
	// task 013 (requirement 17, §11.5): clearing the §11.7 recent-directory
	// history is a real store action (DELETE FROM recent_cwds), not a
	// config.toml key -- config.Schema has nothing to declare for it, the
	// same reason [notify] below has nothing to declare. It is appended to
	// the already-built "ui" category (recent_cwd_limit's own category)
	// rather than getting a category of its own, since it is one action
	// alongside one existing UI-scoped field, not a structured table like
	// [notify]. indexBySection["ui"] is always populated by the walk above
	// (config.Schema always declares at least one ui.* key today), but the
	// lookup stays defensive rather than indexing categories on trust.
	if i, ok := indexBySection["ui"]; ok {
		categories[i].Fields = append(categories[i].Fields, settingsClearRecentCwdsEntry())
	}
	// [notify] is deliberately absent from config.Schema (schema.go's own
	// comment: it is "the stated structural exception", edited via its own
	// dialog per §11.5 rather than flattened into fields). That dialog does
	// not exist this phase (task 029 adds no new dialog), so settings still
	// owes it "a single navigable entry" (§11.5) -- synthesized here, in the
	// TUI layer only, never added to config.Schema itself: task 018's parity
	// test walks config.Schema, and this entry has no backing schema field
	// to be found missing from.
	categories = append(categories, settingsCategory{
		Name:    settingsCategoryName("notify"),
		Section: "notify",
		Fields:  []config.Field{settingsNotifyEntry()},
	})
	// "groups" (task 018, R131 part 1) is a second, deliberately empty-
	// Fields synthetic category, appended last so the existing category
	// walk order (General/UI/Environment/Notify) is undisturbed for every
	// earlier task's own test/scenario sequence. It carries no config.Field
	// entries at all -- unlike [notify]/ui.clear_recent_cwds, a group is
	// not a flat key or a structured config.toml table either, it is a
	// state.db row, so there is nothing here for
	// TestSettingsSchemaParity_EveryRenderedFieldIsBackedBySchema to check
	// against config.Schema. settingsGroupsViewLines (settings.go) renders
	// this category's actual content -- the live m.settingsGroups snapshot
	// -- itself, the same way settingsEnvViewLines takes over rendering for
	// [env] rather than walking a Fields slice.
	categories = append(categories, settingsCategory{
		Name:    "Groups",
		Section: "groups",
	})
	return categories
}

// settingsClearRecentCwdsEntry is task 013's second (after [notify]'s
// settingsNotifyEntry) synthetic settings-only config.Field: requirement
// 17 wants the settings takeover to offer clearing the §11.7 recent-
// directory history, but that history lives in state.db's recent_cwds
// table, never config.toml, so there is no flat key config.Schema could
// declare for it. Its Kind is KindLink -- §11.5's "link (opens the owning
// dialog)" kind is the closest existing shape for "activating this row
// does something other than stage an editable value" -- but, unlike
// [notify]'s link (which opens nothing this phase and says so), enter/
// space here performs the clear immediately (settingsActivateField),
// which is why settingsFieldValueDisplay's KindLink branch special-cases
// its FullKey rather than reusing [notify]'s "opens its own dialog" text:
// nothing here opens, it just clears. FullKey is "ui.clear_recent_cwds"
// (Key set, unlike [notify]/[env]'s Key==""), so settingsFieldLabel's
// generic underscore-splitting path renders its label with no special
// case needed there.
func settingsClearRecentCwdsEntry() config.Field {
	return config.Field{
		Section: "ui",
		Key:     "clear_recent_cwds",
		Kind:    config.KindLink,
		Description: "Clears the §11.7 recent-directory history (state.db's " +
			"recent_cwds table) immediately on enter/space -- not staged, and not " +
			"gated by ctrl+s or esc/discard, since it is a store action rather than " +
			"a config.toml value. The history is non-load-bearing: clearing it " +
			"costs only the create modal's cwd prefill, up/down recent-cycling and " +
			"tab completion candidates (§11.7) the next time it opens. It never " +
			"touches any session row, its cwd, or anything already created, and it " +
			"is never written to the launch audit log or any notification payload " +
			"either way -- the history was never in either of those to begin with.",
		// Not really "lives in config.toml, refreshed live on save" the way
		// ScopeGlobal's other members are -- there is no file value at all --
		// but it shares ScopeGlobal's defining property this schema.go cares
		// about: activating it takes effect in the already-running client
		// immediately, never gated on a restart.
		Scope: config.ScopeGlobal,
	}
}

// settingsNotifyEntry is the synthetic §11.5 "single navigable entry" for
// [notify]: a config.Field the settings takeover renders and lets the user
// select, but which config.Schema never declares and config.FileConfig has
// no member for. Its Kind is KindLink (the exact kind §11.5 reserves for
// "opens the owning dialog"), but activating it opens nothing this phase
// (task 029 adds no notification-rules dialog) -- settingsFieldValueDisplay
// and settingsActivateField both say so explicitly rather than pretending
// the link works.
func settingsNotifyEntry() config.Field {
	return config.Field{
		Section: "notify",
		Kind:    config.KindLink,
		Description: "Channels and delivery rules (SPEC §10) are structured tables " +
			"meant to be edited in their own notification-rules dialog (§11.4), not " +
			"flattened into fields here. That dialog is not implemented this phase: " +
			"this entry is honestly unavailable and opens nothing. Edit [notify] and " +
			"[[notify.rule]] by hand in config.toml until it lands.",
		Scope: config.ScopeGlobal,
	}
}

// settingsFieldLabel renders a schema Field's human label for the
// takeover's field list: the key's underscore-separated words, each
// capitalised ("recent_cwd_limit" -> "Recent Cwd Limit"). The [env] table
// field (Key == "", Section == "env") has no key to derive a label from —
// it is named for what it is instead.
func settingsFieldLabel(f config.Field) string {
	if f.Key == "" && f.Section == "notify" {
		return "Notification Rules"
	}
	if f.Key == "" {
		return "Environment Variables"
	}
	words := strings.Split(f.Key, "_")
	for i, w := range words {
		if w == "" {
			continue
		}
		words[i] = strings.ToUpper(w[:1]) + w[1:]
	}
	return strings.Join(words, " ")
}

// settingsFocus values name which of the takeover's two lists currently
// receives up/down navigation. SPEC §11.5: "tab/left/right switch between
// the category list and the field list, up/down move within the focused
// list."
const (
	settingsFocusCategories = 0
	settingsFocusFields     = 1
)

// updateSettings handles key input while the takeover is open. `/` search
// (task 014) and the discard-confirm prompt (task 016) both take over the
// whole keymap while active, so they are checked first, in the order the
// user can be in at most one of them at a time (the discard prompt only
// ever appears from the main takeover view, never from inside search).
func (m Model) updateSettings(msg tea.KeyMsg) (Model, tea.Cmd) {
	if m.settingsDiscardConfirm {
		return m.updateSettingsDiscardConfirm(msg)
	}
	// task 003's [env] entry editor (requirement 17) takes over the whole
	// keymap while active, the same way the discard-confirm prompt and `/`
	// search already do above/below -- settingsEnvEditing (typing a single
	// entry's key or value) is checked before settingsEnvOpen (browsing
	// the entries list) since the former only ever holds while the latter
	// also does.
	if m.settingsEnvEditing {
		return m.updateSettingsEnvEditing(msg)
	}
	if m.settingsEnvOpen {
		return m.updateSettingsEnvList(msg)
	}
	// The free-text (KindString/KindPath) editor SPEC.md:532 requires for
	// pre_launch/post_destroy takes over the whole keymap for exactly the
	// same reason the [env] entry editor above does: the value being typed
	// is an arbitrary shell command, so `j`, `k`, `/`, `-` and `+` are text
	// here, never navigation/adjust/search -- a mode that let them through
	// would move the selection out from under the value it is about to
	// commit. It cannot be simultaneously true with either settingsEnv*
	// mode (each is entered only from the field list, which the other has
	// already taken over), so the order between them is arbitrary; it sits
	// with them, above `/` search, rather than inside the main switch.
	if m.settingsStringEditing {
		return m.updateSettingsStringEditing(msg)
	}
	// The Groups section's own "n"/"r" typing sub-modes (task 018, R131
	// part 1) take over the whole keymap for the same reason the [env]/
	// free-text editors above do: a typed group name is text, not
	// navigation. Checked in the same tier as those, above `/` search.
	if m.settingsGroupCreating || m.settingsGroupRenaming {
		return m.updateSettingsGroupEditing(msg)
	}
	// task 019/R131 part 2: "d"'s own two-branch prompt on a non-empty
	// group takes over the whole keymap for the same reason -- it is
	// itself a confirm dialog, not a navigable field.
	if m.settingsGroupDeleteConfirming {
		return m.updateSettingsGroupDeleteConfirm(msg)
	}
	if m.settingsSearchActive {
		return m.updateSettingsSearch(msg)
	}
	switch msg.String() {
	case "esc":
		if m.settingsDirty() {
			m.settingsDiscardConfirm = true
			m.settingsNote = ""
		} else {
			m.settingsOpen = false
		}
	case "ctrl+s":
		return m, m.settingsSave()
	case "tab", "left", "right":
		if m.settingsFocus == settingsFocusCategories {
			m.settingsFocus = settingsFocusFields
		} else {
			m.settingsFocus = settingsFocusCategories
		}
	case "up", "k":
		if m.settingsFocus == settingsFocusFields && m.settingsOnGroupsCategory() {
			m.settingsMoveGroupSelection(-1)
		} else {
			m.settingsMove(-1)
		}
	case "down", "j":
		if m.settingsFocus == settingsFocusFields && m.settingsOnGroupsCategory() {
			m.settingsMoveGroupSelection(1)
		} else {
			m.settingsMove(1)
		}
	case "enter", " ":
		m.settingsActivateField()
	case "+", "=":
		m.settingsAdjustField(1)
	case "-", "_":
		m.settingsAdjustField(-1)
	case "/":
		m.settingsSearchActive = true
		m.settingsSearchQuery = ""
		m.settingsSearchIndex = 0
	case "n":
		// R131 part 1: "n" creates a group, reachable ONLY from inside the
		// Groups section's own field panel -- everywhere else in settings
		// (every schema category, the category list itself) it is
		// deliberately unbound, exactly like every other key this switch
		// does not name for a category it does not apply to.
		if m.settingsFocus == settingsFocusFields && m.settingsOnGroupsCategory() {
			m.settingsStartGroupCreate()
		}
	case "r":
		// R131 part 1: "r" renames the selected group, same reachability
		// rule as "n" above, and only when a group is actually selected.
		if m.settingsFocus == settingsFocusFields && m.settingsOnGroupsCategory() {
			m.settingsStartGroupRename()
		}
	case "d":
		// R131 part 2: "d" deletes the selected group, same reachability
		// rule as "n"/"r" above. settingsStartGroupDelete itself decides
		// between an immediate no-prompt delete (empty group) and opening
		// the two-branch confirm (non-empty group) -- "default" is never a
		// row in m.settingsGroups (store.Group's own doc comment) so it can
		// never be selected here at all, which is what "default offers no
		// delete" reduces to.
		if m.settingsFocus == settingsFocusFields && m.settingsOnGroupsCategory() {
			m.settingsStartGroupDelete()
		}
	}
	return m, nil
}

// settingsDirty reports whether the takeover's staged edits (settingsEdits)
// differ from settingsSavedEdits -- the last state actually written to
// config.toml (or, if nothing has been saved yet this session, the state
// the takeover opened with). esc uses this to decide between closing
// outright and requirement 14/20's discard-confirm prompt; comparing
// against settingsSavedEdits rather than settingsEditsFromSettings(m.
// settings) directly means a successful ctrl+s -- which as of task 006
// does refresh m.settings.File and, for ScopeGlobal fields, their resolved
// member too, but always leaves settingsSavedEdits equal to what it just
// wrote either way -- does not leave esc wrongly re-prompting to discard a
// change that is already safely on disk.
func (m Model) settingsDirty() bool {
	return !reflect.DeepEqual(m.settingsEdits, m.settingsSavedEdits)
}

// settingsSave is ctrl+s's effect (SPEC requirement 20): it writes every
// staged edit through config.WriteConfigFile -- task 012's atomic writer,
// so a failure here can never leave config.toml partially written or
// unparseable -- and, only on success, advances settingsSavedEdits to match
// what was just written (settingsCloneFileConfig, so a later mutation of
// settingsEdits.Env cannot alias back into the saved snapshot). A failure
// is surfaced in settingsNote rather than swallowed; settingsEdits is left
// exactly as the user had it either way, so a failed save loses nothing
// and can be retried.
//
// requirement 19 (task 006): on success, before advancing settingsSavedEdits,
// it also refreshes m.settings itself -- both Settings.File (so config.toml
// and the running model's idea of the file never disagree, e.g. on the next
// `,` reopen) and, for every field config.Schema (task 005) declares
// ScopeGlobal, the resolved top-level member the rest of the program
// actually reads (m.settings.AllowYolo/ASCII/Mouse/Theme) -- via
// settingsApplyLiveFields. A ScopeRestartToApply field's file value is still
// refreshed (the file really was just rewritten), but its resolved member is
// deliberately left alone: that member's one consumer only reads it once at
// process start (see the per-field comment in schema.go), so touching it
// here would claim an effect this tree cannot produce. The returned tea.Cmd
// (non-nil only when Mouse's live value changed) is settingsApplyLiveFields'
// way of telling the terminal itself to start/stop emitting SGR mouse
// reports, since that is a runtime command, not a struct field.
func (m *Model) settingsSave() tea.Cmd {
	path := m.settings.Paths.ConfigFile
	if path == "" {
		m.settingsNote = "save failed: no config file path is configured"
		return nil
	}
	if err := config.WriteConfigFile(path, m.settingsEdits); err != nil {
		m.settingsNote = "save failed: " + err.Error()
		return nil
	}
	previous := m.settings.File
	saved := settingsCloneFileConfig(m.settingsEdits)
	m.settings.File = saved
	cmd := m.settingsApplyLiveFields(previous)
	m.settingsSavedEdits = saved
	m.settingsNote = "saved " + path
	return cmd
}

// settingsApplyLiveFields refreshes m.settings for every schema field whose
// Scope (config.Schema, task 005) is ScopeGlobal, comparing the just-saved
// file values against previous (the file values before this save) so only
// fields that actually changed are touched. This is what makes a
// live-applying field's ctrl+s take effect in the already-running client
// without a restart (requirement 19): AllowYolo/ASCII/Mouse copy straight
// across (config.Settings mirrors config.FileConfig for those keys once the
// env-override step -- which this takeover's saved edits never come from,
// per task 001/002 -- is done), and Theme is re-resolved from its saved raw
// name through theme.Resolve the same way config.Load itself does, since
// config.Settings.Theme is a *theme.Theme plus a fallback ThemeReason, not
// the raw string FileConfig.Theme holds (mirroring theme_picker.go's
// themePickerConfirm, so the `,` takeover and the `t` picker agree on how a
// saved theme name reaches the running client).
//
// Mouse additionally needs the terminal itself told to start or stop
// emitting SGR mouse reports: cmd/deck/main.go only applies
// tea.WithMouseCellMotion() once, as a ProgramOption before Run(), so
// flipping m.settings.Mouse alone would silently disagree with what the
// terminal is doing. bubbletea also exposes this as runtime commands
// (screen.go's EnableMouseCellMotion/DisableMouse), so this returns the
// matching one exactly when Mouse's live value changed -- closing the
// turning-it-on gap the existing tea.MouseMsg gate (tui.go's `if
// !m.settings.Mouse { return m, nil }`) only ever covered for turning it
// off.
//
// StaleAfter, CaptureMinInterval, RecentCwdLimit and Env are
// ScopeRestartToApply (schema.go's per-field comment names each one's
// consumer, or lack of one) and are deliberately never touched here: their
// resolved member is not what a save is claimed to affect live.
//
// requirement 21 correction (operator steer 008-envoverride-applylive.md,
// 22 Aug 2026 13:00 BST): a ScopeGlobal field whose key is ALSO named in
// m.settings.EnvOverrides (today only ui.ascii/DECK_ASCII and
// ui.mouse/DECK_MOUSE -- config.LoadFrom's only two override paths) must
// NOT have its resolved member touched here, and for Mouse specifically
// must NOT get the EnableMouseCellMotion/DisableMouse tea.Cmd either --
// §6.5 says the environment outranks the file, and that has to mean the
// ALREADY-RUNNING client too, not just what a fresh process would resolve
// on its next launch. The file value (m.settings.File, config.toml) is
// still written regardless; only the resolved/running side and the
// terminal mouse-reporting command are skipped. See
// settingsFieldEnvOverride for the one map this reuses instead of adding a
// second notion of "overridden".
func (m *Model) settingsApplyLiveFields(previous config.FileConfig) tea.Cmd {
	if m.settingsEdits.AllowYolo != previous.AllowYolo {
		m.settings.AllowYolo = m.settingsEdits.AllowYolo
	}
	if m.settingsEdits.YoloDefault != previous.YoloDefault {
		m.settings.YoloDefault = m.settingsEdits.YoloDefault
	}
	if _, overridden := m.settings.EnvOverrides["ui.ascii"]; !overridden && m.settingsEdits.ASCII != previous.ASCII {
		m.settings.ASCII = m.settingsEdits.ASCII
	}
	if _, overridden := m.settings.EnvOverrides["ui.preview_fit"]; !overridden && m.settingsEdits.PreviewFit != previous.PreviewFit {
		m.settings.PreviewFit = m.settingsEdits.PreviewFit
	}
	// ui.preview_paint: repaintForeignDefaults reads this member on every
	// previewed row, so the next preview tick after a save already paints
	// the new way -- the ScopeGlobal claim its schema entry makes. Guarded
	// by EnvOverrides like every other ScopeGlobal field, and here the
	// guard is live rather than theoretical: DECK_PREVIEW_PAINT is a real
	// override path in config.LoadFrom.
	if _, overridden := m.settings.EnvOverrides["ui.preview_paint"]; !overridden && m.settingsEdits.PreviewPaint != previous.PreviewPaint {
		m.settings.PreviewPaint = m.settingsEdits.PreviewPaint
	}
	var cmd tea.Cmd
	if _, overridden := m.settings.EnvOverrides["ui.mouse"]; !overridden && m.settingsEdits.Mouse != previous.Mouse {
		m.settings.Mouse = m.settingsEdits.Mouse
		enable := m.settingsEdits.Mouse
		// EnableMouseCellMotion/DisableMouse are themselves tea.Msg
		// constructors, not tea.Cmd values (a tea.Cmd is a func() tea.Msg) --
		// wrap the chosen one so bubbletea's runtime dispatches it as the
		// program's next message, exactly as WithMouseCellMotion's own
		// ProgramOption would have if this had been decided at startup.
		if enable {
			cmd = func() tea.Msg { return tea.EnableMouseCellMotion() }
		} else {
			cmd = func() tea.Msg { return tea.DisableMouse() }
		}
	}
	if m.settingsEdits.Theme != previous.Theme {
		userThemes, userErrs := theme.DiscoverUserThemes(theme.ThemesDir(m.settings.Paths.ConfigFile))
		resolved, reason := theme.Resolve(userThemes, userErrs, m.settingsEdits.Theme)
		m.settings.Theme = resolved
		m.settings.ThemeReason = reason
	}
	// requirement R53/task 306: sort_order's schema.go comment names this
	// exact code path as its live-apply consumer. Guarded by EnvOverrides
	// the same way ui.mouse/ui.preview_fit are above -- config.LoadFrom
	// today defines no DECK_SORT_ORDER override at all, so this branch is
	// never actually skipped in practice, but the guard is kept for the
	// same reason every other ScopeGlobal field carries it: an override
	// path added later must not have to remember to add this check too.
	if _, overridden := m.settings.EnvOverrides["ui.sort_order"]; !overridden && m.settingsEdits.SortOrder != previous.SortOrder {
		m.settings.SortOrder = m.settingsEdits.SortOrder
		m.resortSessionsLive()
	}
	return cmd
}

// settingsCloneFileConfig deep-copies cfg's Env map (settingsCloneEnv
// already preserves nil-vs-empty exactly), so settingsSavedEdits never
// aliases the same map settingsEdits keeps mutating; every other member is
// a value type and copies by assignment.
func settingsCloneFileConfig(cfg config.FileConfig) config.FileConfig {
	cfg.Env = settingsCloneEnv(cfg.Env)
	return cfg
}

// updateSettingsDiscardConfirm handles key input while requirement 14's
// discard-confirm prompt is showing (settingsDiscardConfirm, set by esc in
// updateSettings when settingsDirty()). y/enter confirms the discard: the
// takeover closes and settingsEdits is simply dropped along with it --
// config.toml was never touched, so "what survives" is exactly what
// settingsSavedEdits/settingsNote already told the user it would be. Any
// other key (n, esc, or anything else) dismisses the prompt without losing
// the edit, returning the user to the field they were on.
func (m Model) updateSettingsDiscardConfirm(msg tea.KeyMsg) (Model, tea.Cmd) {
	switch msg.String() {
	case "y", "enter":
		m.settingsDiscardConfirm = false
		m.settingsOpen = false
		m.settingsNote = ""
	default:
		m.settingsDiscardConfirm = false
	}
	return m, nil
}

// settingsMove moves the currently focused list's selection by delta,
// wrapping like every other cycled selection in this package. Moving the
// category list resets the field index to 0, since a category swap always
// starts the field list over at its own top (mirroring settingsView's own
// "open on category 0's first field" default).
func (m *Model) settingsMove(delta int) {
	categories := settingsCategories()
	if len(categories) == 0 {
		return
	}
	switch m.settingsFocus {
	case settingsFocusCategories:
		n := len(categories)
		m.settingsCategoryIndex = (m.settingsCategoryIndex + delta + n) % n
		m.settingsFieldIndex = 0
	case settingsFocusFields:
		if m.settingsCategoryIndex < 0 || m.settingsCategoryIndex >= len(categories) {
			return
		}
		fields := categories[m.settingsCategoryIndex].Fields
		if len(fields) == 0 {
			return
		}
		n := len(fields)
		m.settingsFieldIndex = (m.settingsFieldIndex + delta + n) % n
	}
}

// settingsSelectedField returns the field the field-list focus currently
// sits on, or ok=false when categories has focus (nothing to edit there) or
// either index is out of range (an empty category, or a stale index left
// over from a category swap this call raced with the schema -- neither
// happens in practice since settingsMove always resets settingsFieldIndex
// to 0 on a category change, but settingsActivateField/settingsAdjustField
// stay defensive rather than index a slice on trust).
func (m *Model) settingsSelectedField() (config.Field, bool) {
	if m.settingsFocus != settingsFocusFields {
		return config.Field{}, false
	}
	categories := settingsCategories()
	if m.settingsCategoryIndex < 0 || m.settingsCategoryIndex >= len(categories) {
		return config.Field{}, false
	}
	fields := categories[m.settingsCategoryIndex].Fields
	if m.settingsFieldIndex < 0 || m.settingsFieldIndex >= len(fields) {
		return config.Field{}, false
	}
	return fields[m.settingsFieldIndex], true
}

// settingsActivateField is enter/space's effect on the focused field: it
// flips a KindToggle field's staged value, opens task 003's [env] entry
// editor for the KindListOfStrings [env] field (requirement 17 -- the
// field list itself has no room to edit a KEY=VALUE map inline, so enter
// hands focus to a dedicated entries list rather than leaving [env]
// display-only), opens the free-text editor for a KindString/KindPath
// field (SPEC.md:532: pre_launch/post_destroy are "editable in settings
// (§11.5) like every other flat key" -- before this, KindString fell
// through this switch to a silent no-op, so the schema's only two
// free-text keys rendered but refused every key), and otherwise does
// nothing -- notably including the
// [notify] KindLink entry, which §11.5 would have open the notification-
// rules dialog if one existed. Task 029 adds no such dialog this phase, so
// activating that entry is a documented no-op rather than a key that
// silently fails to do what it claims: settingsFieldValueDisplay already
// renders that entry's value as "unavailable this phase".
func (m *Model) settingsActivateField() {
	f, ok := m.settingsSelectedField()
	if !ok {
		return
	}
	switch f.Kind {
	case config.KindToggle:
		settingsSetToggle(&m.settingsEdits, f, !settingsToggleValue(f, m.settingsEdits))
	case config.KindListOfStrings:
		if f.FullKey() == "[env]" {
			m.settingsEnvOpen = true
			m.settingsEnvIndex = 0
			m.settingsEnvEditing = false
			m.settingsEnvReveal = false
		}
	case config.KindString, config.KindPath:
		// Prefilled from the STAGED value (settingsEdits, via
		// settingsStringValue), never from m.settings.File: an edit made
		// earlier this takeover and not yet saved is what the row is
		// showing, so reopening the editor must start from that, not from
		// the file's older value. Both kinds are plain free text to type;
		// KindPath differs only in how settingsFieldValueDisplay renders
		// the committed value (settingsCollapseTilde), which is why one
		// editor serves both -- no schema field is KindPath today, so this
		// arm is exercised only through pre_launch/post_destroy.
		m.settingsStringEditKey = f.FullKey()
		m.settingsStringEditValue = settingsStringValue(f, m.settingsEdits)
		m.settingsStringEditing = true
	case config.KindLink:
		if f.FullKey() == "ui.clear_recent_cwds" {
			m.settingsClearRecentCwds()
		}
	}
}

// settingsClearRecentCwds is task 013/requirement 17's actual effect of
// activating settingsClearRecentCwdsEntry: an immediate
// store.ClearRecentCwds, not staged into m.settingsEdits and not gated by
// ctrl+s -- there is no config.toml value involved at all, so there is
// nothing for esc's discard-confirm (settingsDirty) to catch either way.
// The outcome is surfaced through settingsNote, the same footer-line
// mechanism settingsSave already uses for its own success/failure text,
// rather than a second, parallel notification path.
func (m *Model) settingsClearRecentCwds() {
	if m.store == nil {
		m.settingsNote = "clear recent directories failed: no store is open"
		return
	}
	if err := m.store.ClearRecentCwds(context.Background()); err != nil {
		m.settingsNote = "clear recent directories failed: " + err.Error()
		return
	}
	m.settingsNote = "cleared recent directory history"
}

// settingsOnGroupsCategory reports whether the settings takeover's
// currently selected category is the synthetic "groups" one (task 018).
// Every Groups-specific key binding ("n"/"r", up/down's group-list
// variant) and the dedicated settingsGroupsViewLines render path are
// gated on this, the same way settingsEnvOpen/settingsStringEditing gate
// their own takeover of the keymap and the view.
func (m Model) settingsOnGroupsCategory() bool {
	categories := settingsCategories()
	if m.settingsCategoryIndex < 0 || m.settingsCategoryIndex >= len(categories) {
		return false
	}
	return categories[m.settingsCategoryIndex].Section == "groups"
}

// settingsMoveGroupSelection moves the Groups section's own selection
// (m.settingsGroupIndex, distinct from m.settingsFieldIndex since this
// category's Fields list is always empty -- settingsCategories' own doc
// comment) by delta, wrapping like every other cycled selection in this
// package (settingsMove's own precedent). A no-op on an empty group list.
func (m *Model) settingsMoveGroupSelection(delta int) {
	n := len(m.settingsGroups)
	if n == 0 {
		return
	}
	m.settingsGroupIndex = (m.settingsGroupIndex + delta + n) % n
}

// settingsSelectedGroup returns the group m.settingsGroupIndex currently
// points at, or ok=false when the list is empty or the index is out of
// range (defensive, mirroring settingsSelectedField's own stance --
// settingsMoveGroupSelection always keeps the index in range by
// construction, but "r" and a rename commit stay defensive rather than
// index a slice on trust).
func (m Model) settingsSelectedGroup() (store.Group, bool) {
	if m.settingsGroupIndex < 0 || m.settingsGroupIndex >= len(m.settingsGroups) {
		return store.Group{}, false
	}
	return m.settingsGroups[m.settingsGroupIndex], true
}

// settingsStartGroupCreate opens "n"'s typing sub-mode: an empty buffer,
// no target id (0 -- meaningless while creating, settingsCommitGroupEdit
// dispatches on m.settingsGroupCreating/m.settingsGroupRenaming, never on
// whether the id happens to be zero), and a cleared note so a stale error
// from a previous attempt never lingers into a fresh one.
func (m *Model) settingsStartGroupCreate() {
	m.settingsGroupCreating = true
	m.settingsGroupRenaming = false
	m.settingsGroupEditID = 0
	m.settingsGroupEditValue = ""
	m.settingsGroupNote = ""
}

// settingsStartGroupRename opens "r"'s typing sub-mode on the currently
// selected group, prefilled with its current name -- mirroring renameView's
// own "prefilled with the session's current name" precedent (rename.go) --
// or does nothing when no group is selected (an empty list).
func (m *Model) settingsStartGroupRename() {
	g, ok := m.settingsSelectedGroup()
	if !ok {
		return
	}
	m.settingsGroupRenaming = true
	m.settingsGroupCreating = false
	m.settingsGroupEditID = g.ID
	m.settingsGroupEditValue = g.Name
	m.settingsGroupNote = ""
}

// settingsStartGroupDelete is "d"'s effect on the currently selected
// group (task 019, R131 part 2): the group's COMPLETE persisted member set
// (groupMemberSessions -- active AND archived sessions, never just
// m.baseSessions' archive-free default view) decides empty-vs-non-empty.
// Empty (no members at all, archived included) is dropped immediately via
// store.DeleteGroup, with no prompt at all ("there is nothing to decide"),
// while a non-empty one opens the two-branch confirm sub-mode instead of
// deleting anything yet, with the resolved member set frozen onto
// m.settingsGroupDeleteMembers for that confirm's own later use (the
// prompt's count, "m"'s move loop, and "d"'s hand-off to the bulk dd path
// all read that same frozen slice rather than re-querying three times).
// Does nothing when no group is selected (an empty list) -- and "default"
// can never reach here in the first place, since it is never a row in
// m.settingsGroups to begin with.
func (m *Model) settingsStartGroupDelete() {
	g, ok := m.settingsSelectedGroup()
	if !ok {
		return
	}
	if m.store == nil {
		m.settingsGroupNote = "no store is open"
		return
	}
	members, err := m.groupMemberSessions(context.Background(), g.ID)
	if err != nil {
		m.settingsGroupNote = err.Error()
		return
	}
	if len(members) == 0 {
		m.settingsDeleteEmptyGroupNow(g)
		return
	}
	m.settingsGroupDeleteConfirming = true
	m.settingsGroupDeleteID = g.ID
	m.settingsGroupDeleteName = g.Name
	m.settingsGroupDeleteMembers = members
	m.settingsGroupNote = ""
}

// settingsDeleteEmptyGroupNow is settingsStartGroupDelete's no-prompt
// branch: store.DeleteGroup outright (there are no members to decide
// anything about), then the same refresh/reselect/note dance
// settingsCommitGroupEdit's own create/rename branches already use.
func (m *Model) settingsDeleteEmptyGroupNow(g store.Group) {
	if m.store == nil {
		m.settingsGroupNote = "no store is open"
		return
	}
	if err := m.store.DeleteGroup(context.Background(), g.ID); err != nil {
		m.settingsGroupNote = err.Error()
		return
	}
	m.settingsGroups = m.computeAvailableGroups()
	if m.settingsGroupIndex >= len(m.settingsGroups) && m.settingsGroupIndex > 0 {
		m.settingsGroupIndex--
	}
	m.settingsGroupNote = "deleted empty group " + g.Name
}

// updateSettingsGroupDeleteConfirm handles key input while "d"'s
// two-branch confirm sub-mode is open (task 019, R131 part 2, SPEC §11.5's
// carve-out): "m" is the non-destructive branch (move every member to
// default, then drop the group row -- destroying nothing),
// "d" is the destructive branch, handed off wholesale to the EXISTING
// §9.2 bulk `dd` confirm rather than a second deletion implementation, and
// esc abandons the whole sub-mode, writing nothing.
func (m Model) updateSettingsGroupDeleteConfirm(msg tea.KeyMsg) (Model, tea.Cmd) {
	switch msg.String() {
	case "esc":
		m.settingsGroupDeleteConfirming = false
		m.settingsGroupDeleteID = 0
		m.settingsGroupDeleteName = ""
		m.settingsGroupDeleteMembers = nil
		m.settingsGroupNote = ""
		return m, nil
	case "m":
		return m, m.settingsMoveGroupMembersToDefaultAndDeleteGroup()
	case "d":
		m.settingsRouteGroupDeleteToBulkConfirm()
		return m, nil
	}
	return m, nil
}

// settingsMoveGroupMembersToDefaultAndDeleteGroup is "m"'s commit (task
// 019, R131 part 2's non-destructive branch): every current member
// (re-read from m.baseSessions right now, never a stale snapshot) is moved
// to the structural default group (store.SetSessionGroup with groupID 0,
// SetSessionGroup's own "<=0 means default" contract) before the group row
// itself is dropped (store.DeleteGroup) -- ordered that way on purpose, so
// a mid-loop failure never leaves the group row gone while a member still
// names it (which would just degrade that member to default anyway per
// SPEC §11's dangling-group_id rule, but leaving the row alone on error is
// simpler to reason about). Returns m.loadSessions so the already-loaded
// session list picks up every member's new group_id right away, mirroring
// the `g` picker's own submitGroupMove precedent, rather than waiting for
// the next periodic reconcile.
func (m *Model) settingsMoveGroupMembersToDefaultAndDeleteGroup() tea.Cmd {
	if m.store == nil {
		m.settingsGroupNote = "no store is open"
		return nil
	}
	id, name := m.settingsGroupDeleteID, m.settingsGroupDeleteName
	members := m.settingsGroupDeleteMembers
	ctx := context.Background()
	now := time.Now()
	if m.settings.Clock != nil {
		now = m.settings.Clock.Now()
	}
	at := now.UnixMilli()
	for _, s := range members {
		if err := m.store.SetSessionGroup(ctx, s.ID, 0, "user", at); err != nil {
			m.settingsGroupNote = err.Error()
			return nil
		}
	}
	if err := m.store.DeleteGroup(ctx, id); err != nil {
		m.settingsGroupNote = err.Error()
		return nil
	}
	m.settingsGroups = m.computeAvailableGroups()
	if m.settingsGroupIndex >= len(m.settingsGroups) && m.settingsGroupIndex > 0 {
		m.settingsGroupIndex--
	}
	m.settingsGroupDeleteConfirming = false
	m.settingsGroupDeleteID = 0
	m.settingsGroupDeleteName = ""
	m.settingsGroupDeleteMembers = nil
	m.settingsGroupNote = "deleted group " + name + " -- its sessions moved to default"
	return m.loadSessions
}

// settingsRouteGroupDeleteToBulkConfirm is "d"'s commit inside the
// two-branch confirm (task 019, R131 part 2's destructive branch): it
// populates m.marked with exactly the group's current members (re-read
// from m.baseSessions right now) and sets the very same fields the main
// list's own second-`d` dd chord sets for a non-empty mark set
// (Update's own pendingDelete branch, the dd chord's second key) --
// m.deleteConfirming,
// m.deleteScroll reset, m.bulkDeletePurgeValue defaulted to "keep" (cure-01-05:
// the destructive branch reaches the SAME bulk confirm, so it offers the
// SAME non-default purge choice) -- so control reaches
// updateBulkDeleteConfirm/bulkDeleteConfirmBody through the exact same seam
// `dd` does, never a second deletion implementation. The settings takeover
// itself closes (m.settingsOpen =
// false): deleteConfirming is already checked ahead of settingsOpen in
// both Update and View, so the confirm would render either way, but
// closing settings here is what lets the ORDINARY top-level `u` (only
// reachable once nothing else has taken over the keymap) restore the
// whole batch afterward, exactly like any other dd.
//
// The group ROW itself is not touched here: PRD R131 puts it at "once the
// batch commits", so the id is parked on m.bulkDeleteGroupID and the
// sessionsBulkDeleted branch drops the row after every member's delete has
// actually succeeded (cancelling the confirm clears it instead, leaving
// the group intact). A later `u` restores the sessions but not the group:
// their group_id no longer resolves, which SPEC §11's dangling-group_id
// rule already renders as default rather than crashing.
func (m *Model) settingsRouteGroupDeleteToBulkConfirm() {
	members := m.settingsGroupDeleteMembers
	marked := make(map[string]bool, len(members))
	for _, s := range members {
		marked[s.ID] = true
	}
	m.bulkDeleteGroupID = m.settingsGroupDeleteID
	m.bulkDeleteGroupName = m.settingsGroupDeleteName
	// The complete member set (archived included) is handed to the shared
	// dd seam VERBATIM here, via bulkDeleteSessions -- never re-derived from
	// m.marked through markedSessions(), which would filter it back down to
	// whatever the sidebar's current view (and any active filter) happens
	// to show. m.marked is still populated alongside it, for the sidebar's
	// own mark rendering if settings reopens mid-batch; bulkDeleteBatch
	// never reads it while bulkDeleteSessions is set.
	m.bulkDeleteSessions = members
	m.settingsGroupDeleteConfirming = false
	m.settingsGroupDeleteID = 0
	m.settingsGroupDeleteName = ""
	m.settingsGroupDeleteMembers = nil
	m.settingsGroupNote = ""
	m.settingsOpen = false
	m.marked = marked
	m.deleteConfirming = true
	m.deleteNote = ""
	m.deleteScroll = 0
	// cure-01-05: same default as the ordinary mark-set path above -- the
	// destructive branch reaches the SAME bulk confirm, so it must offer
	// the SAME non-default purge choice, reset to "keep" every time this
	// hand-off happens.
	m.bulkDeletePurgeValue = "keep"
	m.deletePurgeValue = ""
	m.deletePurgePath = ""
	m.deletePurgeOK = false
}

// updateSettingsGroupEditing handles key input while "n"/"r"'s typing
// sub-mode is open (m.settingsGroupCreating or m.settingsGroupRenaming):
// typed runes extend m.settingsGroupEditValue, backspace shortens it BY
// ONE RUNE (settingsStringEditing's own precedent -- a group name is
// user-typed text that may contain a multi-byte rune), enter commits
// through settingsCommitGroupEdit, and esc abandons the sub-mode with no
// trace at all: unlike settingsDiscardConfirm, there is nothing here for
// esc to discard, since nothing has been written to state.db yet (SPEC
// §11.5: creating/renaming takes effect only on this commit, not on every
// keystroke).
func (m Model) updateSettingsGroupEditing(msg tea.KeyMsg) (Model, tea.Cmd) {
	switch msg.String() {
	case "esc":
		m.settingsGroupCreating = false
		m.settingsGroupRenaming = false
		m.settingsGroupEditID = 0
		m.settingsGroupEditValue = ""
		m.settingsGroupNote = ""
		return m, nil
	case "enter":
		m.settingsCommitGroupEdit()
		return m, nil
	case "backspace", "ctrl+h":
		if r := []rune(m.settingsGroupEditValue); len(r) > 0 {
			m.settingsGroupEditValue = string(r[:len(r)-1])
		}
		return m, nil
	}
	if runes := msg.Runes; len(runes) > 0 {
		m.settingsGroupEditValue += string(runes)
	}
	return m, nil
}

// settingsCommitGroupEdit is enter's effect inside the Groups typing
// sub-mode: it calls store.CreateGroup/RenameGroup (task 009) SYNCHRONOUSLY
// -- mirroring settingsClearRecentCwds' own precedent for an immediate,
// non-staged store action -- and writes to state.db right now, never
// through m.settingsEdits/config.WriteConfigFile, per SPEC §11.5's "takes
// effect immediately" rule for the group list. A validation error (task
// 009's validateGroupName -- a reserved/duplicate/too-long/control-
// character name) is surfaced verbatim in m.settingsGroupNote and the
// typing sub-mode is left OPEN with the rejected value still in the
// buffer, so the user can correct it in place rather than losing what
// they typed; only a successful commit closes the sub-mode and refreshes
// m.settingsGroups (computeAvailableGroups' own precedent) so the newly
// created/renamed group is immediately visible and selected.
func (m *Model) settingsCommitGroupEdit() {
	if m.store == nil {
		m.settingsGroupNote = "no store is open"
		return
	}
	ctx := context.Background()
	switch {
	case m.settingsGroupCreating:
		g, err := m.store.CreateGroup(ctx, m.settingsGroupEditValue)
		if err != nil {
			m.settingsGroupNote = err.Error()
			return
		}
		m.settingsGroups = m.computeAvailableGroups()
		m.selectSettingsGroupByID(g.ID)
		m.settingsGroupNote = "created group " + g.Name
	case m.settingsGroupRenaming:
		if err := m.store.RenameGroup(ctx, m.settingsGroupEditID, m.settingsGroupEditValue); err != nil {
			m.settingsGroupNote = err.Error()
			return
		}
		renamedID := m.settingsGroupEditID
		m.settingsGroups = m.computeAvailableGroups()
		m.selectSettingsGroupByID(renamedID)
		m.settingsGroupNote = "renamed group"
	default:
		return
	}
	m.settingsGroupCreating = false
	m.settingsGroupRenaming = false
	m.settingsGroupEditID = 0
	m.settingsGroupEditValue = ""
}

// selectSettingsGroupByID points m.settingsGroupIndex at id's row in the
// just-refreshed m.settingsGroups, or leaves it untouched (0, harmlessly,
// on the zero Model) when id is not found -- it always is right after a
// successful create/rename, since computeAvailableGroups is a live re-read
// of the very row that commit just wrote.
func (m *Model) selectSettingsGroupByID(id int64) {
	for i, g := range m.settingsGroups {
		if g.ID == id {
			m.settingsGroupIndex = i
			return
		}
	}
}

// settingsEnvKeys returns cfg.Env's keys in a stable (sorted) order, so
// the entries list settingsEnvViewLines renders and the index
// settingsEnvIndex selects agree on which row is which across renders --
// Go map iteration order is randomised, so nothing else in this package
// may walk cfg.Env directly for display or selection.
func settingsEnvKeys(cfg config.FileConfig) []string {
	keys := make([]string, 0, len(cfg.Env))
	for k := range cfg.Env {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	return keys
}

// updateSettingsEnvList handles key input while the [env] entries list has
// taken over the field panel (m.settingsEnvOpen, m.settingsEnvEditing
// false): up/down move the selection across every staged entry plus a
// trailing "add entry" row, enter opens the selected entry (or a blank one
// for "add entry") for editing, "-"/"_" removes the selected entry
// outright (mirroring +/-'s existing "adjust this field" verb rather than
// binding a new key the footer would have to learn to name), and esc
// leaves the entries list and returns to the field list -- no key here is
// new: every one is already bound and named by settingsFooterLine.
func (m Model) updateSettingsEnvList(msg tea.KeyMsg) (Model, tea.Cmd) {
	keys := settingsEnvKeys(m.settingsEdits)
	n := len(keys) + 1
	switch msg.String() {
	case "esc":
		m.settingsEnvOpen = false
	case "up", "k":
		m.settingsEnvIndex = (m.settingsEnvIndex - 1 + n) % n
	case "down", "j":
		m.settingsEnvIndex = (m.settingsEnvIndex + 1) % n
	case "enter", " ":
		switch {
		case m.settingsEnvIndex == len(keys):
			m.settingsEnvEditKey = ""
			m.settingsEnvEditValue = ""
			m.settingsEnvEditOriginalKey = ""
			m.settingsEnvEditingKeyPart = true
			m.settingsEnvEditing = true
		case m.settingsEnvIndex >= 0 && m.settingsEnvIndex < len(keys):
			key := keys[m.settingsEnvIndex]
			m.settingsEnvEditKey = key
			m.settingsEnvEditValue = m.settingsEdits.Env[key]
			m.settingsEnvEditOriginalKey = key
			m.settingsEnvEditingKeyPart = false
			m.settingsEnvEditing = true
		}
	case "-", "_":
		m.settingsEnvDeleteSelected()
	case "r":
		// SPEC §6.4/requirement 21: the explicit per-view reveal toggle.
		m.settingsEnvReveal = !m.settingsEnvReveal
	}
	return m, nil
}

// settingsEnvDeleteSelected removes the entries list's currently selected
// entry from m.settingsEdits.Env (never m.settingsSavedEdits -- deleting
// only stages the removal, ctrl+s/esc still govern whether it ever
// reaches config.toml, exactly like every other field kind's edit) and
// clamps settingsEnvIndex back onto the shorter list. Selecting the
// trailing "add entry" row and pressing "-" is a no-op: there is nothing
// there to remove.
func (m *Model) settingsEnvDeleteSelected() {
	keys := settingsEnvKeys(m.settingsEdits)
	if m.settingsEnvIndex < 0 || m.settingsEnvIndex >= len(keys) {
		return
	}
	delete(m.settingsEdits.Env, keys[m.settingsEnvIndex])
	n := len(settingsEnvKeys(m.settingsEdits)) + 1
	if m.settingsEnvIndex >= n {
		m.settingsEnvIndex = n - 1
	}
}

// updateSettingsEnvEditing handles key input while a single [env] entry's
// key or value is being typed (m.settingsEnvEditing): typed runes extend
// whichever of settingsEnvEditKey/settingsEnvEditValue tab currently
// targets (settingsEnvEditingKeyPart), backspace shortens it, tab swaps
// which one is being typed, enter on the key moves to the value without
// committing yet and enter on the value commits the whole entry
// (settingsEnvCommitEdit) and returns to the entries list, and esc
// discards the buffer and returns to the entries list without touching
// settingsEdits.Env at all.
func (m Model) updateSettingsEnvEditing(msg tea.KeyMsg) (Model, tea.Cmd) {
	switch msg.String() {
	case "esc":
		m.settingsEnvEditing = false
		return m, nil
	case "tab":
		m.settingsEnvEditingKeyPart = !m.settingsEnvEditingKeyPart
		return m, nil
	case "enter":
		if m.settingsEnvEditingKeyPart {
			m.settingsEnvEditingKeyPart = false
			return m, nil
		}
		m.settingsEnvCommitEdit()
		m.settingsEnvEditing = false
		return m, nil
	case "backspace", "ctrl+h":
		if m.settingsEnvEditingKeyPart {
			if r := []rune(m.settingsEnvEditKey); len(r) > 0 {
				m.settingsEnvEditKey = string(r[:len(r)-1])
			}
		} else {
			if r := []rune(m.settingsEnvEditValue); len(r) > 0 {
				m.settingsEnvEditValue = string(r[:len(r)-1])
			}
		}
		return m, nil
	}
	if runes := msg.Runes; len(runes) > 0 {
		if m.settingsEnvEditingKeyPart {
			m.settingsEnvEditKey += string(runes)
		} else {
			m.settingsEnvEditValue += string(runes)
		}
	}
	return m, nil
}

// settingsEnvCommitEdit stages the currently-edited [env] entry into
// m.settingsEdits.Env: an empty (after trimming) key commits nothing --
// updateSettingsEnvEditing still leaves editing mode, so an operator who
// backspaces a key to nothing and hits enter simply abandons the entry
// rather than staging a blank-named variable. A non-empty key that
// differs from settingsEnvEditOriginalKey (a rename, or a brand new entry
// where the original is "") removes the original key first, so renaming
// never leaves both the old and new key staged at once. settingsEnvIndex
// is left on the committed entry's row in the entries list's own sorted
// order.
func (m *Model) settingsEnvCommitEdit() {
	key := strings.TrimSpace(m.settingsEnvEditKey)
	if key == "" {
		return
	}
	if m.settingsEdits.Env == nil {
		m.settingsEdits.Env = map[string]string{}
	}
	if m.settingsEnvEditOriginalKey != "" && m.settingsEnvEditOriginalKey != key {
		delete(m.settingsEdits.Env, m.settingsEnvEditOriginalKey)
	}
	m.settingsEdits.Env[key] = m.settingsEnvEditValue
	for i, k := range settingsEnvKeys(m.settingsEdits) {
		if k == key {
			m.settingsEnvIndex = i
			break
		}
	}
}

// updateSettingsStringEditing handles key input while a KindString/KindPath
// field's value is being typed (m.settingsStringEditing), the free-text
// counterpart to updateSettingsEnvEditing and deliberately the same shape:
// typed runes extend settingsStringEditValue, backspace shortens it BY ONE
// RUNE (a []rune round-trip, never a byte slice -- a hook command may well
// contain multi-byte text, and trimming one byte off a multi-byte rune
// would stage invalid UTF-8 into config.toml), enter commits through
// settingsSetString and returns to the field list, and esc discards the
// buffer without touching settingsEdits at all.
//
// A committed EMPTY string is a real value here, not a cancel: "" is
// exactly how a user says "no global hook" (schema.go's own default), so
// enter on an emptied buffer must clear the key -- unlike
// settingsEnvCommitEdit, where an empty KEY names no variable and so can
// only be an abandoned entry. esc remains the only way to leave without
// staging anything.
//
// ctrl+s is deliberately swallowed rather than treated as "commit, then
// save": the takeover's save writes every staged edit to config.toml, and
// doing that from inside a half-typed command would put text the user was
// still editing on disk behind their back. Enter is this mode's single,
// explicit commit gesture (the footer says so), and ctrl+s works the
// instant it is pressed -- the same one-keystroke cost the [env] entry
// editor already imposes, which swallows ctrl+s for the same reason.
func (m Model) updateSettingsStringEditing(msg tea.KeyMsg) (Model, tea.Cmd) {
	switch msg.String() {
	case "esc":
		m.settingsStringEditing = false
		return m, nil
	case "enter":
		m.settingsStringCommitEdit()
		m.settingsStringEditing = false
		return m, nil
	case "backspace", "ctrl+h":
		if r := []rune(m.settingsStringEditValue); len(r) > 0 {
			m.settingsStringEditValue = string(r[:len(r)-1])
		}
		return m, nil
	case "ctrl+s":
		return m, nil
	}
	// Every printable keystroke -- including a lone space, which bubbletea
	// reports as tea.KeySpace but still carries in Runes (key.go's own
	// "for backwards compatibility" naming), and each rune of a keystroke
	// burst Update already split rune-by-rune (task 118) -- is text.
	if runes := msg.Runes; len(runes) > 0 {
		m.settingsStringEditValue += string(runes)
	}
	return m, nil
}

// settingsStringCommitEdit stages the typed value into m.settingsEdits
// through settingsSetString -- the same generic per-kind setter
// settingsSave and task 018's parity test already drive, so nothing about
// the dirty/save flow needs to know this editor exists: settingsDirty()
// compares settingsEdits against settingsSavedEdits and therefore goes
// true on its own the moment this writes a different value, and ctrl+s
// then writes it through config.WriteConfigFile like any other field's
// edit.
//
// It commits only when the still-selected field is the one the editor was
// opened on (settingsStringEditField): the editing mode owns the whole
// keymap, so the selection cannot move while it is active, and this guard
// exists so that if that ever stops being true the value lands nowhere
// rather than on some other key.
func (m *Model) settingsStringCommitEdit() {
	f, ok := m.settingsStringEditField()
	if !ok {
		return
	}
	settingsSetString(&m.settingsEdits, f, m.settingsStringEditValue)
}

// settingsStringEditField resolves the schema field the free-text editor is
// open on, from the live settingsCategories() walk rather than a
// config.Field copied into the Model when the editor opened -- the same
// "read the schema, never a second copy of it" rule settingsCategories'
// own doc comment sets for this file. settingsStringEditKey (the FullKey
// captured on open) is checked against the current selection so a
// mismatch is reported as "no field" instead of silently committing to
// whatever is selected now.
func (m Model) settingsStringEditField() (config.Field, bool) {
	f, ok := m.settingsSelectedField()
	if !ok || f.FullKey() != m.settingsStringEditKey {
		return config.Field{}, false
	}
	return f, true
}

// settingsAdjustField is +/-'s effect on the focused field: step a
// KindInteger field's staged value by delta (settingsSetInteger clamps to
// the field's declared Bounds, so this can never stage a value the file
// writer or the schema-driven parser would reject), or cycle a KindEnum
// field's staged value through settingsFieldOptions. Every other kind has
// no notion of a "next" value and is left untouched.
func (m *Model) settingsAdjustField(delta int) {
	f, ok := m.settingsSelectedField()
	if !ok {
		return
	}
	switch f.Kind {
	case config.KindInteger:
		settingsSetInteger(&m.settingsEdits, f, settingsIntegerValue(f, m.settingsEdits)+delta)
	case config.KindEnum:
		options := m.settingsFieldOptions(f)
		if len(options) == 0 {
			return
		}
		cur := settingsEnumValue(f, m.settingsEdits)
		idx := 0
		for i, o := range options {
			if o == cur {
				idx = i
			}
		}
		idx = ((idx+delta)%len(options) + len(options)) % len(options)
		settingsSetEnum(&m.settingsEdits, f, options[idx])
	}
}

// settingsEditsFromSettings seeds the takeover's staged working copy
// (Model.settingsEdits) from config.Settings.File -- the values exactly as
// parsed from config.toml, before any DECK_* environment override -- never
// from the env-resolved fields Settings otherwise exposes for the rest of
// the program to consume. Requirement 21: a save must edit the file's own
// value for a key, never the value an environment variable substituted
// into the running Settings for that same key; seeding from the resolved
// fields would silently launder an env override into config.toml the
// moment `,` is pressed and ctrl+s follows with no edit at all. Unlike the
// pre-task-001 version, Theme needs no resolved-value fallback either:
// config.FileConfig already carries the raw configured name (s.File.Theme),
// not just the theme.Theme SPEC §11.6 resolved it to.
func settingsEditsFromSettings(s config.Settings) config.FileConfig {
	return config.FileConfig{
		AllowYolo:            s.File.AllowYolo,
		YoloDefault:          s.File.YoloDefault,
		StaleAfter:           s.File.StaleAfter,
		CaptureMinInterval:   s.File.CaptureMinInterval,
		InteractiveMS:        s.File.InteractiveMS,
		InteractiveTransport: s.File.InteractiveTransport,
		TmuxMouse:            s.File.TmuxMouse,
		ASCII:                s.File.ASCII,
		Mouse:                s.File.Mouse,
		PreviewFit:           s.File.PreviewFit,
		PreviewPaint:         s.File.PreviewPaint,
		SortOrder:            s.File.SortOrder,
		RecentCwdLimit:       s.File.RecentCwdLimit,
		EventRetentionDays:   s.File.EventRetentionDays,
		Theme:                s.File.Theme,
		PreLaunch:            s.File.PreLaunch,
		PostDestroy:          s.File.PostDestroy,
		Env:                  settingsCloneEnv(s.File.Env),
	}
}

func settingsCloneEnv(env map[string]string) map[string]string {
	if env == nil {
		return nil
	}
	out := make(map[string]string, len(env))
	for k, v := range env {
		out[k] = v
	}
	return out
}

// settingsToggleValue/settingsSetToggle, settingsIntegerValue/
// settingsSetInteger and settingsEnumValue/settingsSetEnum are the get/set
// pair for every KindToggle/KindInteger/KindEnum field config.Schema
// actually declares today. Each mirrors toml.go's setField and
// toml_write.go's serializeFieldValue: one generic dispatch per Kind, with
// a FullKey switch beneath it that carries no logic of its own (Go structs
// have no by-name-string field access without reflection) -- adding a
// future schema field of an already-supported kind means one case here,
// not a new code path.
func settingsToggleValue(f config.Field, cfg config.FileConfig) bool {
	switch f.FullKey() {
	case "allow_yolo":
		return cfg.AllowYolo
	case "yolo_default":
		return cfg.YoloDefault
	case "tmux_mouse":
		return cfg.TmuxMouse
	case "ui.ascii":
		return cfg.ASCII
	case "ui.mouse":
		return cfg.Mouse
	case "ui.preview_fit":
		return cfg.PreviewFit
	default:
		b, _ := f.Default.(bool)
		return b
	}
}

func settingsSetToggle(cfg *config.FileConfig, f config.Field, v bool) {
	switch f.FullKey() {
	case "allow_yolo":
		cfg.AllowYolo = v
	case "yolo_default":
		cfg.YoloDefault = v
	case "tmux_mouse":
		cfg.TmuxMouse = v
	case "ui.ascii":
		cfg.ASCII = v
	case "ui.mouse":
		cfg.Mouse = v
	case "ui.preview_fit":
		cfg.PreviewFit = v
	}
}

func settingsIntegerValue(f config.Field, cfg config.FileConfig) int {
	switch f.FullKey() {
	case "stale_after":
		return int(cfg.StaleAfter.Seconds())
	case "capture_min_interval":
		return int(cfg.CaptureMinInterval.Seconds())
	case "interactive_ms":
		return int(cfg.InteractiveMS.Milliseconds())
	case "ui.recent_cwd_limit":
		return cfg.RecentCwdLimit
	case "event_retention_days":
		return cfg.EventRetentionDays
	default:
		v, _ := f.Default.(int)
		return v
	}
}

// settingsSetInteger clamps v to field's declared IntBounds before writing
// it into cfg, so +/- (or a future direct-entry editor) can never stage an
// out-of-bounds value the atomic writer or the schema-driven reader would
// then have to reject on the next load.
func settingsSetInteger(cfg *config.FileConfig, f config.Field, v int) {
	if v < f.IntBounds.Min {
		v = f.IntBounds.Min
	}
	if f.IntBounds.Max != nil && v > *f.IntBounds.Max {
		v = *f.IntBounds.Max
	}
	switch f.FullKey() {
	case "stale_after":
		cfg.StaleAfter = time.Duration(v) * time.Second
	case "capture_min_interval":
		cfg.CaptureMinInterval = time.Duration(v) * time.Second
	case "interactive_ms":
		cfg.InteractiveMS = time.Duration(v) * time.Millisecond
	case "ui.recent_cwd_limit":
		cfg.RecentCwdLimit = v
	case "event_retention_days":
		cfg.EventRetentionDays = v
	}
}

func settingsEnumValue(f config.Field, cfg config.FileConfig) string {
	switch f.FullKey() {
	case "ui.theme":
		return cfg.Theme
	case "ui.sort_order":
		return cfg.SortOrder
	case "ui.preview_paint":
		return cfg.PreviewPaint
	case "interactive_transport":
		return cfg.InteractiveTransport
	default:
		s, _ := f.Default.(string)
		return s
	}
}

func settingsSetEnum(cfg *config.FileConfig, f config.Field, v string) {
	switch f.FullKey() {
	case "ui.theme":
		cfg.Theme = v
	case "ui.sort_order":
		cfg.SortOrder = v
	case "ui.preview_paint":
		cfg.PreviewPaint = v
	case "interactive_transport":
		cfg.InteractiveTransport = v
	}
}

// settingsFieldOptions resolves a KindEnum field's cycle-through choices.
// ui.theme is §11.6's DynamicEnum case (schema.go: "the schema cannot list
// a fixed choice set because a dropped-in user theme file changes it
// without a code change"), so its options are resolved here, at render/
// edit time, from the same theme.Builtins()/theme.DiscoverUserThemes the
// rest of the program uses to resolve a configured name -- never a second,
// hand-maintained theme name list.
func (m Model) settingsFieldOptions(f config.Field) []string {
	switch f.FullKey() {
	case "ui.theme":
		return settingsThemeOptions(m.settings.Paths)
	default:
		return f.EnumValues
	}
}

func settingsThemeOptions(paths config.Paths) []string {
	var names []string
	for _, t := range theme.Builtins() {
		names = append(names, t.Name)
	}
	sort.Strings(names)
	userThemes, _ := theme.DiscoverUserThemes(theme.ThemesDir(paths.ConfigFile))
	var userNames []string
	for name := range userThemes {
		userNames = append(userNames, name)
	}
	sort.Strings(userNames)
	return append(names, userNames...)
}

// settingsFieldValueDisplay renders field f's current staged value (from
// cfg) exactly as §11.5 requires per kind: On/Off for a toggle, the number
// plus its declared unit and bounds for a bounded integer, the raw string
// for a plain string, a path collapsed back to `~` form for KindPath (the
// display-side counterpart of expandCreateCWD's ~-expansion, task 011.7),
// the selected choice for an enum, an entry count for list-of-strings, and
// the honest "unavailable this phase" for [notify]'s KindLink entry rather
// than a value it does not have. Every kind config.FieldKind names is
// handled explicitly, including the three (string, path, link other than
// notify) config.Schema happens not to use today, so a future schema
// addition of one of those kinds renders correctly on day one.
// settingsFieldEnvOverride reports whether config.Settings.EnvOverrides
// (§6.5: "Environment always outranks the file") named f as overridden in
// THIS environment, and by which DECK_* variable, so both the field row
// (settingsFieldLabel's caller) and its detail lines (settingsField
// DetailLines) can say so without a second, hand-maintained copy of which
// keys env can override -- the map config.LoadFrom already built while
// resolving env-over-file precedence is the only source of truth read
// here.
func settingsFieldEnvOverride(f config.Field, s config.Settings) (string, bool) {
	if len(s.EnvOverrides) == 0 {
		return "", false
	}
	envVar, ok := s.EnvOverrides[f.FullKey()]
	return envVar, ok
}

// settingsFieldRunningValueDisplay renders field f's actual running value,
// read off the resolved config.Settings s -- the value the already-running
// client is using right now -- as opposed to settingsFieldValueDisplay's
// staged/file value from m.settingsEdits. Requirement 21's honesty fix
// needs both named on screen for an env-overridden field, since they can
// legitimately disagree (that disagreement is exactly what "overridden by
// environment" means). config.LoadFrom today only ever overrides ui.ascii
// and ui.mouse (both KindToggle), so those are the only cases with a real
// answer; every other key falls back to fallback (the file value already
// computed), since nothing can override it and the two must be equal.
func settingsFieldRunningValueDisplay(f config.Field, s config.Settings, fallback string) string {
	onOff := func(b bool) string {
		if b {
			return "On"
		}
		return "Off"
	}
	switch f.FullKey() {
	case "ui.ascii":
		return onOff(s.ASCII)
	case "ui.mouse":
		return onOff(s.Mouse)
	case "ui.preview_fit":
		return onOff(s.PreviewFit)
	case "ui.preview_paint":
		return s.PreviewPaint
	default:
		return fallback
	}
}

func settingsFieldValueDisplay(f config.Field, cfg config.FileConfig) string {
	switch f.Kind {
	case config.KindToggle:
		v := settingsToggleValue(f, cfg)
		text := "Off"
		if v {
			text = "On"
		}
		// steer 017 item 2: yolo_default=true with allow_yolo=false is a
		// stated, visible inconsistency in THIS row's own text -- never a
		// silent override of either key in either direction (allow_yolo
		// does not flip on because of this, and this does not get silently
		// cleared/ignored either).
		if f.FullKey() == "yolo_default" && v && !cfg.AllowYolo {
			text += " (inert: allow_yolo is off, so this has no effect yet)"
		}
		return text
	case config.KindInteger:
		v := settingsIntegerValue(f, cfg)
		text := strconv.Itoa(v)
		if f.Unit != "" {
			text += " " + f.Unit
		}
		if bounds := settingsIntegerBoundsText(f); bounds != "" {
			text += " (" + bounds + ")"
		}
		return text
	case config.KindEnum:
		v := settingsEnumValue(f, cfg)
		if v == "" {
			return "(default)"
		}
		return v
	case config.KindString:
		return settingsStringPlaceholder(settingsStringValue(f, cfg))
	case config.KindPath:
		return settingsStringPlaceholder(settingsCollapseTilde(settingsStringValue(f, cfg)))
	case config.KindListOfStrings:
		return settingsListValueDisplay(f, cfg)
	case config.KindLink:
		switch f.FullKey() {
		case "[notify]":
			return "unavailable this phase"
		case "ui.clear_recent_cwds":
			return "press enter/space to clear now"
		default:
			return "opens its own dialog"
		}
	default:
		return fmt.Sprintf("%v", f.Default)
	}
}

// settingsIntegerBoundsText renders a KindInteger field's declared Bounds
// as the parenthetical settingsFieldValueDisplay appends, e.g. "1-50" or
// "min 1" when there is no documented upper bound (Bounds.Max == nil).
func settingsIntegerBoundsText(f config.Field) string {
	if f.Kind != config.KindInteger {
		return ""
	}
	if f.IntBounds.Max != nil {
		return fmt.Sprintf("%d-%d", f.IntBounds.Min, *f.IntBounds.Max)
	}
	return fmt.Sprintf("min %d", f.IntBounds.Min)
}

// settingsStringValue is KindString's get, generic across any schema
// field of that kind, matching settingsToggleValue/settingsIntegerValue/
// settingsEnumValue's own dispatch shape.
func settingsStringValue(f config.Field, cfg config.FileConfig) string {
	switch f.FullKey() {
	case "pre_launch":
		return cfg.PreLaunch
	case "post_destroy":
		return cfg.PostDestroy
	default:
		s, _ := f.Default.(string)
		return s
	}
}

// settingsStringPlaceholder renders an empty free-text value as
// "(not set)" rather than as nothing at all, borrowing KindEnum's existing
// "(default)" idiom above for the same reason: both hook keys default to ""
// (schema.go), and a row that rendered "Pre Launch: " with an empty value
// read as a broken row rather than an unset one -- there was no way to tell
// "no hook configured" from "settings failed to render this". The
// parenthesised form can never be mistaken for a real value, since a shell
// command a user typed is staged verbatim and only ever displayed through
// this, never re-parsed from it.
func settingsStringPlaceholder(v string) string {
	if v == "" {
		return "(not set)"
	}
	return v
}

// settingsSetString is settingsStringValue's set half, the KindString
// counterpart to settingsSetToggle/settingsSetInteger/settingsSetEnum.
func settingsSetString(cfg *config.FileConfig, f config.Field, v string) {
	switch f.FullKey() {
	case "pre_launch":
		cfg.PreLaunch = v
	case "post_destroy":
		cfg.PostDestroy = v
	}
}

// settingsCollapseTilde is the display-side inverse of tui.go's
// expandCreateCWD: a path under the current user's home directory renders
// with that prefix collapsed to `~`, matching how a user who typed `~/...`
// into a path field would expect to see it read back, rather than the
// fully-expanded absolute form expandCreateCWD stores. A path outside the
// home directory, or one os.UserHomeDir cannot resolve, is returned
// unchanged.
func settingsCollapseTilde(path string) string {
	home, err := os.UserHomeDir()
	if err != nil || home == "" {
		return path
	}
	if path == home {
		return "~"
	}
	if strings.HasPrefix(path, home+string(os.PathSeparator)) {
		return "~" + path[len(home):]
	}
	return path
}

// settingsListValueDisplay is KindListOfStrings' get. [env] (Key == "") is
// the one real schema field of this kind: its "list" is really a
// KEY=VALUE map, so rendering every entry inline would crowd the field
// list (and leak env values into a screenshot); an entry count is shown
// instead, matching §11.5's own framing of [env] as "opens" the concept of
// many entries rather than one flat value (the actual per-entry editor
// this implies is out of scope for task 015, which owns per-kind display,
// not a nested table editor -- see settingsFieldDetailLines' description
// text for the honest statement of what changing it does).
func settingsListValueDisplay(f config.Field, cfg config.FileConfig) string {
	if f.FullKey() == "[env]" {
		n := len(cfg.Env)
		switch n {
		case 0:
			return "0 entries"
		case 1:
			return "1 entry"
		default:
			return fmt.Sprintf("%d entries", n)
		}
	}
	if list, ok := f.Default.([]string); ok {
		if len(list) == 0 {
			return "(empty)"
		}
		return strings.Join(list, ", ")
	}
	return "(empty)"
}

// settingsFieldDetailLines renders the currently selected field's kind,
// scope and description underneath its own row in the field list --
// §11.5's "each field states what it does and what changes when it
// changes" plus the scope label requirement, both read verbatim off the
// schema Field rather than a second, hand-written copy of either. width is
// the field panel's usable content width; wrapText keeps a long
// description from being truncated away instead of wrapped across lines.
//
// Requirement 21: when envVar is non-empty (this field is env-overridden),
// the detail text must state BOTH values by name -- fileValue (what
// config.toml holds, and what an edit-and-save here changes) and
// runningValue (what the already-running client is actually using right
// now, per envVar, until envVar is unset) -- and must not phrase saving as
// changing the running value. Before this, the text named envVar three
// times but never said what either value actually was, so "the running
// value comes from DECK_ASCII" read as a claim about DECK_ASCII's value,
// not this field's two distinct values.
func settingsFieldDetailLines(f config.Field, width int, envVar, fileValue, runningValue string) []string {
	if width < 1 {
		width = 1
	}
	lines := []string{fmt.Sprintf("Kind: %s \u00b7 Scope: %s", f.Kind, f.Scope)}
	if envVar != "" {
		lines = append(lines, wrapText(fmt.Sprintf("Overridden by environment: %s is set, so the running value is %s, not this file's %s, until %s is unset. Editing and saving here changes only config.toml's value (currently %s); the running client keeps using %s's %s until it is unset.", envVar, runningValue, fileValue, envVar, fileValue, envVar, runningValue), width)...)
	}
	lines = append(lines, wrapText(f.Description, width)...)
	return lines
}

// settingsSearchResult pairs a schema field matched by a `/` query with the
// category/field indices selecting it (enter, task 014) or rendering it
// (task 015) lands on.
type settingsSearchResult struct {
	CategoryIndex int
	FieldIndex    int
	Field         config.Field
}

// settingsFuzzyMatch is the small "fuzzy" §11.5's field search needs: every
// whitespace-separated token of query must appear as a case-insensitive
// substring of target, in any order. A query of "" matches everything (the
// search box starts empty and shows every field until the user types).
func settingsFuzzyMatch(query, target string) bool {
	target = strings.ToLower(target)
	for _, tok := range strings.Fields(strings.ToLower(query)) {
		if !strings.Contains(target, tok) {
			return false
		}
	}
	return true
}

// settingsSearchMatches searches every schema field's label AND
// description (§11.5: "/ ... searches every field by label and
// description") and returns matches in schema order, each carrying the
// category/field indices that select it.
func settingsSearchMatches(query string) []settingsSearchResult {
	var results []settingsSearchResult
	for ci, cat := range settingsCategories() {
		for fi, f := range cat.Fields {
			label := settingsFieldLabel(f)
			if settingsFuzzyMatch(query, label) || settingsFuzzyMatch(query, f.Description) {
				results = append(results, settingsSearchResult{CategoryIndex: ci, FieldIndex: fi, Field: f})
			}
		}
	}
	return results
}

// updateSettingsSearch handles key input while the `/` search box is
// active: typed runes extend the query, backspace shortens it, up/down
// move among the current matches, enter jumps the two lists to the
// highlighted match and leaves search mode with focus on the field list,
// and esc leaves search mode (clearing the query) without moving the
// selection -- mirroring the closing-without-saving shape task 016 will
// give the takeover as a whole, but scoped to just the search box.
func (m Model) updateSettingsSearch(msg tea.KeyMsg) (Model, tea.Cmd) {
	switch msg.String() {
	case "esc":
		m.settingsSearchActive = false
		m.settingsSearchQuery = ""
		m.settingsSearchIndex = 0
		return m, nil
	case "enter":
		results := settingsSearchMatches(m.settingsSearchQuery)
		if m.settingsSearchIndex >= 0 && m.settingsSearchIndex < len(results) {
			match := results[m.settingsSearchIndex]
			m.settingsCategoryIndex = match.CategoryIndex
			m.settingsFieldIndex = match.FieldIndex
			m.settingsFocus = settingsFocusFields
		}
		m.settingsSearchActive = false
		m.settingsSearchQuery = ""
		m.settingsSearchIndex = 0
		return m, nil
	case "backspace", "ctrl+h":
		if q := m.settingsSearchQuery; q != "" {
			r := []rune(q)
			m.settingsSearchQuery = string(r[:len(r)-1])
		}
		m.settingsSearchIndex = 0
		return m, nil
	case "up", "ctrl+p":
		if n := len(settingsSearchMatches(m.settingsSearchQuery)); n > 0 {
			m.settingsSearchIndex = (m.settingsSearchIndex - 1 + n) % n
		}
		return m, nil
	case "down", "ctrl+n":
		if n := len(settingsSearchMatches(m.settingsSearchQuery)); n > 0 {
			m.settingsSearchIndex = (m.settingsSearchIndex + 1) % n
		}
		return m, nil
	}
	if runes := msg.Runes; len(runes) > 0 {
		m.settingsSearchQuery += string(runes)
		m.settingsSearchIndex = 0
	}
	return m, nil
}

// settingsCategoryWidth picks the left category panel's width the same way
// ComputeLayout picks the sidebar's: a fraction of the total width, clamped
// to a floor that keeps every category name legible and a ceiling that
// leaves the field list (the panel that actually carries the field's
// description text, task 015) the majority of the screen.
func settingsCategoryWidth(width int) int {
	w := width / 3
	const floor, ceil = 20, 30
	if w < floor {
		w = floor
	}
	if w > ceil {
		w = ceil
	}
	if width-w < floor {
		w = width - floor
	}
	if w < 1 {
		w = 1
	}
	return w
}

// settingsRowSegment pairs one run of text with the theme token it renders
// in, so settingsRenderRow can compose a "label: value" row (SPEC
// requirement 34: labels in `hint`, values in `text`) as several
// differently-coloured runs on one line.
type settingsRowSegment struct {
	Text string
	Tok  theme.Token
}

// settingsListLine (task 322/R58c) pairs one row's already-composed text
// (via settingsRenderRowOpen, so it carries no background of its own and
// no closing reset) with the background token, if any, that row wants --
// mirroring sidebarRowLines/sidebarContentLine's own split of concerns
// (tui.go:3356/panel.go:487, task 321/R58b) exactly: this file used to open
// a row's background inside settingsRenderRow and close it the moment that
// row's own text ended, the same bug task 321 fixed for the sidebar, one
// level removed. settingsLeftContentLine/settingsRightContentLine are now
// the only two places that open bg (once) and close it (once), spanning
// the row's pad-fill and flanking padding columns too. The zero value
// (text "", bg "") is exactly what fitLines' generic zero-fill wants for
// an unused trailing row -- no background, matching a truly empty string
// row under the old []string shape.
type settingsListLine struct {
	text string
	bg   theme.Token
}

// settingsRenderRowOpen composes segs' own foreground colours -- opening
// no background of its own and never emitting a closing reset -- so a
// caller that wants a background to span PAST this text (task 321/R58b:
// the sidebar row highlight filling the whole panel width, pad-fill and
// flanking padding columns included, not just the glyphs sidebarRowLines
// happens to draw; task 322/R58c: every settings-takeover list row for
// exactly the same reason, one level removed) can open that background
// before this text and close everything with exactly one reset of its
// own -- an inner reset here would clear the outer caller's background
// the instant this text's own last segment ended. Every settingsListLine
// (settings.go's category/field/env-entry/search-result rows) and
// sidebarRowLines compose their text through this, never through a
// self-closing per-row render, precisely because both always have an
// outer bg-spanning wrapper (settingsLeftContentLine/
// settingsRightContentLine/sidebarContentLine) that needs the trailing
// reset left to it.
func (m Model) settingsRenderRowOpen(segs []settingsRowSegment) string {
	var b strings.Builder
	if !m.settings.Color {
		for _, s := range segs {
			b.WriteString(s.Text)
		}
		return b.String()
	}
	for _, s := range segs {
		if seq, ok := m.foregroundSGR(s.Tok); ok {
			b.WriteString(seq)
		}
		b.WriteString(s.Text)
	}
	return b.String()
}

// settingsSelectionToken resolves which of SPEC requirement 42's two
// focus-cue tokens a list's currently-selected row renders in: `selection`
// when that list is the one tab/left/right currently gives up/down to,
// `selection_idle` otherwise -- both lists always show their own
// highlighted row, distinguished by which token, never by one list's
// highlight disappearing outright.
func (m Model) settingsSelectionToken(list int) theme.Token {
	if m.settingsFocus == list {
		return theme.Selection
	}
	return theme.SelectionIdle
}

// settingsBorderColor renders a border glyph run in `border_focus` (SPEC
// requirement 42) when the panel it belongs to is the one currently
// focused, or `border` otherwise. The settings takeover's two lists are
// deck's only second focusable surface -- §11.3's main view has exactly
// one focusable region, which is why `tab` is unbound there (requirement
// 42). Task 021 generalised the same border_focus/border split to every
// other panel this package draws (panel.go's borderColor, now token-
// parametrised rather than the old removed placeholder m.color()); this
// remains
// its own function only because the settings takeover's focus state
// (m.settingsFocus, not "is this the sidebar or the preview") is what
// picks the token here.
func (m Model) settingsBorderColor(focused bool, text string) string {
	tok := theme.Border
	if focused {
		tok = theme.BorderFocus
	}
	return m.colorToken(tok, text)
}

// settingsLeftTopLine/settingsLeftBottomLine/settingsLeftContentLine draw
// the category panel's (left, sidebar-shaped) border with the focus cue
// above; geometry matches panel.go's sidebarTopLine/sidebarBottomLine/
// sidebarContentLine exactly -- only the colour source differs.
func (m Model) settingsLeftTopLine(width int, title string, focused bool) string {
	bc := m.box()
	inner := width - 1
	label, remain := m.borderLabel(title, inner)
	return m.canvasBackground(theme.Background,
		m.settingsBorderColor(focused, bc.topLeft), label, m.settingsBorderColor(focused, strings.Repeat(bc.horizontal, remain)))
}

func (m Model) settingsLeftBottomLine(width int, focused bool) string {
	bc := m.box()
	return m.canvasBackground(theme.Background,
		m.settingsBorderColor(focused, bc.bottomLeft), m.settingsBorderColor(focused, strings.Repeat(bc.horizontal, width-1)))
}

// settingsLeftContentLine mirrors sidebarContentLine's own bg fallback
// (task 004/005, R118): l.bg == "" resolves to theme.Background rather
// than to no background at all, so the border+pad+text+pad span composes
// through ONE canvasBackground call the same way sidebarContentLine's
// does, instead of the hand-rolled per-call "seq + text + reset" this
// used before task 005.
func (m Model) settingsLeftContentLine(width int, l settingsListLine, focused bool) string {
	bc := m.box()
	border := m.settingsBorderColor(focused, bc.vertical)
	padded := m.padTrunc(l.text, width-3)
	base := l.bg
	if base == "" {
		base = theme.Background
	}
	return m.canvasBackground(base, border, " ", padded, " ")
}

// settingsRightTopLine/settingsRightBottomLine/settingsRightContentLine
// mirror panel.go's previewTopLine/previewBottomLine/previewContentLine
// with seam=true (the settings takeover is always side-by-side, never
// stacked) but the focus-cue colour source above instead of borderColor.
func (m Model) settingsRightTopLine(width int, title string, focused bool) string {
	bc := m.box()
	inner := width - 2
	label, remain := m.borderLabel(title, inner)
	return m.canvasBackground(theme.Background,
		m.settingsBorderColor(focused, bc.seamTop), label, m.settingsBorderColor(focused, strings.Repeat(bc.horizontal, remain)), m.settingsBorderColor(focused, bc.topRight))
}

func (m Model) settingsRightBottomLine(width int, focused bool) string {
	bc := m.box()
	inner := width - 2
	return m.canvasBackground(theme.Background,
		m.settingsBorderColor(focused, bc.seamBottom), m.settingsBorderColor(focused, strings.Repeat(bc.horizontal, inner)), m.settingsBorderColor(focused, bc.bottomRight))
}

// settingsRightContentLine mirrors fullBoxContentLine's own bg fallback
// (task 004/005, R118): l.bg == "" resolves to theme.Background, and the
// whole border+pad+text+pad+border span composes through ONE
// canvasBackground call instead of the hand-rolled per-call
// "seq + text + reset" this used before task 005.
func (m Model) settingsRightContentLine(width int, l settingsListLine, focused bool) string {
	bc := m.box()
	border := m.settingsBorderColor(focused, bc.vertical)
	inner := width - 4
	padded := m.padTrunc(l.text, inner)
	base := l.bg
	if base == "" {
		base = theme.Background
	}
	return m.canvasBackground(base, border, " ", padded, " ", border)
}

// settingsView renders the full-screen takeover: a category list panel and
// a field list panel sharing one seam. Geometry (corner/seam glyphs,
// column widths) matches panel.go's sidebarTopLine/sidebarContentLine/
// sidebarBottomLine and previewTopLine/previewContentLine/previewBottomLine
// exactly — SPEC requirement 16's "bordered like every other panel, dialog
// and overlay" with one geometry, not two — but colour comes from the
// settingsLeft*/settingsRight*/settingsRenderRow helpers above so the two
// lists' focus cue (border_focus/border, selection/selection_idle, SPEC
// requirement 42) and the field rows' label/value distinction (`hint`/
// `text`, requirement 34) render from theme tokens rather than the
// colourless placeholder tasks 013-018 left in place.
func (m Model) settingsView() string {
	width, height := m.frameSize()
	leftWidth := settingsCategoryWidth(width)
	rightWidth := width - leftWidth
	// One row for the top border, one for the bottom border, one for the
	// footer line below the frame (mirroring mainView's own footerLine).
	contentRows := height - 3
	if contentRows < 0 {
		contentRows = 0
	}

	categories := settingsCategories()
	leftFocused := m.settingsFocus == settingsFocusCategories
	rightFocused := m.settingsFocus == settingsFocusFields

	if m.settingsSearchActive {
		return m.settingsSearchViewLines(categories, leftWidth, rightWidth, contentRows, height)
	}
	if m.settingsEnvOpen {
		return m.settingsEnvViewLines(categories, leftWidth, rightWidth, contentRows, height)
	}
	if m.settingsStringEditing {
		return m.settingsStringEditViewLines(categories, leftWidth, rightWidth, contentRows, height)
	}
	// The Groups section (task 018, R131 part 1) is rendered by its own
	// dedicated path whenever it is the selected category -- whether
	// focus is on the category list or the field list, and whether "n"/
	// "r"'s typing sub-mode is open -- exactly like settingsEnvViewLines/
	// settingsStringEditViewLines above take over rendering for their own
	// sub-modes, since this category's Fields list is always empty and has
	// nothing for the generic per-field walk below to draw.
	if m.settingsOnGroupsCategory() {
		return m.settingsGroupsViewLines(categories, leftWidth, rightWidth, contentRows, height)
	}

	categorySelTok := m.settingsSelectionToken(settingsFocusCategories)
	leftLines := make([]settingsListLine, len(categories))
	for i, cat := range categories {
		marker := "  "
		selected := i == m.settingsCategoryIndex
		if selected {
			marker = "> "
		}
		bg := theme.Token("")
		if selected {
			bg = categorySelTok
		}
		leftLines[i] = settingsListLine{text: m.settingsRenderRowOpen([]settingsRowSegment{{Text: marker + cat.Name, Tok: theme.Text}}), bg: bg}
	}
	leftLines = fitLines(leftLines, contentRows)

	fieldSelTok := m.settingsSelectionToken(settingsFocusFields)
	var rightLines []settingsListLine
	if m.settingsCategoryIndex >= 0 && m.settingsCategoryIndex < len(categories) {
		fields := categories[m.settingsCategoryIndex].Fields
		innerWidth := rightWidth - 4
		for i, f := range fields {
			marker := "  "
			selected := i == m.settingsFieldIndex
			if selected {
				marker = "> "
			}
			fileValue := settingsFieldValueDisplay(f, m.settingsEdits)
			valueText := fileValue
			if envVar, ok := settingsFieldEnvOverride(f, m.settings); ok {
				runningValue := settingsFieldRunningValueDisplay(f, m.settings, fileValue)
				// Kept short ("overridden by ENVVAR, running: VALUE", not the
				// longer detail-line phrasing) so it never exceeds the field
				// panel's own row budget (66 visible cells at the harness's
				// 100-column default) and gets silently truncated away by
				// padTrunc -- the fuller statement lives in the detail lines
				// below, which have wrapText's whole multi-line budget. Appended
				// onto valueText (one segment, one Tok) rather than a second
				// settingsRowSegment: settingsRenderRow opens a fresh SGR escape
				// per segment even when consecutive segments share the same
				// theme.Token, which would otherwise split "Off (file value..."
				// across an escape boundary invisible to a human but fatal to a
				// plain substring assertion against the coloured view.
				valueText += " (file value; overridden by " + envVar + ", running: " + runningValue + ")"
			}
			segs := []settingsRowSegment{
				{Text: marker, Tok: theme.Text},
				{Text: settingsFieldLabel(f), Tok: theme.Hint},
				{Text: ": ", Tok: theme.Text},
				{Text: valueText, Tok: theme.Text},
			}
			fieldBg := theme.Token("")
			if selected {
				fieldBg = fieldSelTok
			}
			rightLines = append(rightLines, settingsListLine{text: m.settingsRenderRowOpen(segs), bg: fieldBg})
			if selected {
				envVar, _ := settingsFieldEnvOverride(f, m.settings)
				runningValue := settingsFieldRunningValueDisplay(f, m.settings, fileValue)
				for _, detail := range settingsFieldDetailLines(f, innerWidth-2, envVar, fileValue, runningValue) {
					rightLines = append(rightLines, settingsListLine{text: "    " + detail})
				}
			}
		}
	}
	rightLines = fitLines(rightLines, contentRows)

	lines := make([]string, 0, height)
	lines = append(lines, m.settingsLeftTopLine(leftWidth, "Categories", leftFocused)+m.settingsRightTopLine(rightWidth, "Fields", rightFocused))
	for i := 0; i < contentRows; i++ {
		lines = append(lines, m.settingsLeftContentLine(leftWidth, leftLines[i], leftFocused)+m.settingsRightContentLine(rightWidth, rightLines[i], rightFocused))
	}
	lines = append(lines, m.settingsLeftBottomLine(leftWidth, leftFocused)+m.settingsRightBottomLine(rightWidth, rightFocused))
	lines = append(lines, m.settingsFooterLine())
	return strings.Join(lines, "\n")
}

// settingsFooterLine names every key the takeover currently binds:
// task 013's esc, task 014's tab/left/right/up-down/`/`, task 015's
// enter/space (toggle) and +/- (adjust a bounded integer or cycle an
// enum), and task 016's ctrl+s (save) -- never a key bound here but left
// unnamed, the same "advertises a key it doesn't grant"/"binds a key it
// doesn't name" defect the §11.4 dialog contract (task 029) forbids for
// the five dialogs. While the discard-confirm prompt or `/` search is
// active, the line instead names only the keys valid in that sub-mode.
//
// Like mainView's own footerLine (tui.go, task 004/R118), the composed
// text is painted through canvasBackground so every cell this line
// occupies -- normal, discard-confirm, search, [env] list, [env] edit and
// the free-text string editor alike -- carries theme.Background across
// the whole settings takeover's own footer row, rather than leaving it to
// the terminal's own background the way it was left before this cure.
// settingsFooterLineContent below is the line's own text composition,
// unchanged byte-for-byte from before this wrapping was added, so every
// existing assertion against the footer's literal text (search for
// "ctrl+s save", the discard prompt's own wording, etc.) keeps passing
// against either function.
// The content is padded out to the terminal's full width before painting,
// for the same reason mainView's footerLine is (operator request,
// 2026-09-18): this is the bottom row directly under the takeover's own
// frame, so a line painted only under its text leaves a straight
// half-painted seam across the screen.
func (m Model) settingsFooterLine() string {
	width, _ := m.frameSize()
	return m.canvasFillLine(theme.Background, m.settingsFooterLineContent(), width)
}

// settingsFooterLineContent is settingsFooterLine's own composition,
// before the canvas paint wrapping above.
func (m Model) settingsFooterLineContent() string {
	width, _ := m.frameSize()
	if m.settingsDiscardConfirm {
		return truncateToWidth("discard unsaved changes and keep config.toml as last saved? y/enter discards - any other key cancels", width)
	}
	if m.settingsSearchActive {
		return truncateToWidth("type to search - up/down select - enter jump - esc cancel", width)
	}
	if m.settingsEnvEditing {
		return truncateToWidth("type to edit - tab switch key/value - enter on value saves the entry - esc cancels", width)
	}
	if m.settingsEnvOpen {
		return truncateToWidth("up/down move - enter edit/add - - remove - r reveal/mask - esc back to fields", width)
	}
	if m.settingsStringEditing {
		// Names ctrl+s too, even though this mode swallows it
		// (updateSettingsStringEditing): "ctrl+s saves after enter" states
		// the one thing an operator mid-edit would otherwise get wrong, and
		// a footer that stayed silent about the takeover's own save key
		// while a mode disabled it would be the same "binds a key it does
		// not name" defect in reverse.
		return truncateToWidth("type to edit - enter stages the value - esc cancels - ctrl+s saves after enter", width)
	}
	// The Groups section's own typing sub-mode (task 018): esc really does
	// cancel outright here, never "stage" -- unlike the string editor
	// above, nothing this footer names is later gated by ctrl+s, since
	// creating/renaming a group commits straight to state.db on enter.
	if m.settingsGroupCreating {
		return truncateToWidth("type a group name - enter creates it now - esc cancels", width)
	}
	if m.settingsGroupRenaming {
		return truncateToWidth("type a new name - enter renames it now - esc cancels", width)
	}
	// task 019/R131 part 2's own two-branch confirm sub-mode, same tier as
	// the create/rename typing sub-modes just above.
	if m.settingsGroupDeleteConfirming {
		return truncateToWidth("m moves members to default and drops the group - d deletes them too (same confirm section 9.2's dd uses) - esc cancels", width)
	}
	if m.settingsOnGroupsCategory() {
		// R131 part 1/2: "n"/"r"/"d" are named here instead of in the
		// generic footer below, since they are reachable only from this one
		// category (settingsOnGroupsCategory's own doc comment) -- naming
		// them in every other category's footer would be the "advertises a
		// key it doesn't grant" defect this package already avoids for
		// every other sub-mode-only binding.
		footer := "tab/left/right switch - up/down select - n new group - r rename - d delete - esc close"
		if m.settingsGroupNote != "" {
			footer = m.settingsGroupNote + " - " + footer
		}
		return truncateToWidth(footer, width)
	}
	footer := "tab/left/right switch - up/down move - enter/+/- edit - / search - ctrl+s save - esc close"
	if m.settingsNote != "" {
		footer = m.settingsNote + " - " + footer
	}
	return truncateToWidth(footer, width)
}

// settingsEnvViewLines renders the takeover while task 003's [env] entry
// editor has taken over the field panel (m.settingsEnvOpen): the left
// panel keeps showing the category list unchanged and unfocused (editing
// [env] never moves the category selection), and the right panel becomes
// the entries list -- one row per m.settingsEdits.Env key in
// settingsEnvKeys' stable order, each rendered "KEY=VALUE", plus a
// trailing "+ add entry" row -- or, while m.settingsEnvEditing is also
// true, the single key/value being typed with the field currently
// receiving keystrokes named so an operator mid-edit can see which of the
// two tab currently targets.
func (m Model) settingsEnvViewLines(categories []settingsCategory, leftWidth, rightWidth, contentRows, height int) string {
	const leftFocused, rightFocused = false, true

	leftLines := make([]settingsListLine, len(categories))
	for i, cat := range categories {
		leftLines[i] = settingsListLine{text: m.settingsRenderRowOpen([]settingsRowSegment{{Text: "  " + cat.Name, Tok: theme.Text}})}
	}
	leftLines = fitLines(leftLines, contentRows)

	var rightLines []settingsListLine
	var title string
	if m.settingsEnvEditing {
		title = "Edit [env] entry"
		keyMarker, valueMarker := "  ", "  "
		keyBg, valueBg := theme.Token(""), theme.Token("")
		if m.settingsEnvEditingKeyPart {
			keyMarker = "> "
			keyBg = theme.Selection
		} else {
			valueMarker = "> "
			valueBg = theme.Selection
		}
		rightLines = []settingsListLine{
			{text: m.settingsRenderRowOpen([]settingsRowSegment{{Text: keyMarker + "Key: " + m.settingsEnvEditKey, Tok: theme.Text}}), bg: keyBg},
			{text: m.settingsRenderRowOpen([]settingsRowSegment{{Text: valueMarker + "Value: " + m.maskEnvValue(m.settingsEnvEditKey, m.settingsEnvEditValue, m.settingsEnvReveal), Tok: theme.Text}}), bg: valueBg},
		}
	} else {
		title = "[env]"
		keys := settingsEnvKeys(m.settingsEdits)
		rightLines = make([]settingsListLine, 0, len(keys)+1)
		for i, k := range keys {
			marker := "  "
			selected := i == m.settingsEnvIndex
			if selected {
				marker = "> "
			}
			segs := []settingsRowSegment{
				{Text: marker, Tok: theme.Text},
				{Text: k, Tok: theme.Hint},
				{Text: "=", Tok: theme.Text},
				{Text: m.maskEnvValue(k, m.settingsEdits.Env[k], m.settingsEnvReveal), Tok: theme.Text},
			}
			bg := theme.Token("")
			if selected {
				bg = theme.Selection
			}
			rightLines = append(rightLines, settingsListLine{text: m.settingsRenderRowOpen(segs), bg: bg})
		}
		addMarker := "  "
		addSelected := m.settingsEnvIndex == len(keys)
		addBg := theme.Token("")
		if addSelected {
			addMarker = "> "
			addBg = theme.Selection
		}
		rightLines = append(rightLines, settingsListLine{text: m.settingsRenderRowOpen([]settingsRowSegment{{Text: addMarker + "+ add entry", Tok: theme.Hint}}), bg: addBg})
	}
	rightLines = fitLines(rightLines, contentRows)

	lines := make([]string, 0, height)
	lines = append(lines, m.settingsLeftTopLine(leftWidth, "Categories", leftFocused)+m.settingsRightTopLine(rightWidth, title, rightFocused))
	for i := 0; i < contentRows; i++ {
		lines = append(lines, m.settingsLeftContentLine(leftWidth, leftLines[i], leftFocused)+m.settingsRightContentLine(rightWidth, rightLines[i], rightFocused))
	}
	lines = append(lines, m.settingsLeftBottomLine(leftWidth, leftFocused)+m.settingsRightBottomLine(rightWidth, rightFocused))
	lines = append(lines, m.settingsFooterLine())
	return strings.Join(lines, "\n")
}

// settingsTextCursor is the trailing cursor indicator every free-text field
// this package draws already uses (env_editor.go's session [env] value row,
// filter.go's `/` query line): a single "_" after the last typed rune. It
// is a plain ASCII byte, so it needs no m.settings.ASCII fallback and costs
// exactly one display column wherever it lands.
const settingsTextCursor = "_"

// settingsStringEditViewLines renders the takeover while the free-text
// (KindString/KindPath) editor SPEC.md:532 requires has taken over the
// field panel (m.settingsStringEditing): the left panel keeps showing the
// category list unchanged and unfocused (typing a hook command never moves
// the category selection), exactly as settingsEnvViewLines does, and the
// right panel becomes the single value being typed -- panel title "Edit
// <label>" so the row's identity survives leaving the field list, the text
// itself with settingsTextCursor at the end, and the field's own kind/
// scope/description detail lines beneath, because a hook is
// restart-to-apply (schema.go) and that is worth stating while the value is
// being typed rather than only before and after.
//
// The value is hard-wrapped (settingsWrapVerbatim) rather than word-wrapped
// through wrapText: wrapText splits on strings.Fields, which collapses runs
// of whitespace, so a command with two spaces between its arguments would
// be DISPLAYED differently from the text about to be staged. A wrapped
// value can also never widen the panel -- each row is built to the panel's
// own inner width and settingsRightContentLine's padTrunc still bounds it
// -- and fitLines below caps the row count at the frame's budget, so an
// absurdly long command cannot push the bottom border off screen either.
func (m Model) settingsStringEditViewLines(categories []settingsCategory, leftWidth, rightWidth, contentRows, height int) string {
	const leftFocused, rightFocused = false, true

	leftLines := make([]settingsListLine, len(categories))
	for i, cat := range categories {
		leftLines[i] = settingsListLine{text: m.settingsRenderRowOpen([]settingsRowSegment{{Text: "  " + cat.Name, Tok: theme.Text}})}
	}
	leftLines = fitLines(leftLines, contentRows)

	innerWidth := rightWidth - 4
	title := "Edit value"
	f, haveField := m.settingsStringEditField()
	if haveField {
		title = "Edit " + settingsFieldLabel(f)
	}

	var rightLines []settingsListLine
	// The whole typed block carries the `selection` background, not just
	// its first row: it is one field receiving keystrokes, so a highlight
	// that stopped at the first wrapped row would read as two rows, one of
	// them inert (requirement 42's focus cue names the surface that has
	// the keystrokes, not a single line of it).
	for i, chunk := range settingsWrapVerbatim(m.settingsStringEditValue+settingsTextCursor, innerWidth-2) {
		marker := "  "
		if i == 0 {
			marker = "> "
		}
		rightLines = append(rightLines, settingsListLine{
			text: m.settingsRenderRowOpen([]settingsRowSegment{{Text: marker + chunk, Tok: theme.Text}}),
			bg:   theme.Selection,
		})
	}
	if haveField {
		envVar, _ := settingsFieldEnvOverride(f, m.settings)
		fileValue := settingsFieldValueDisplay(f, m.settingsEdits)
		runningValue := settingsFieldRunningValueDisplay(f, m.settings, fileValue)
		for _, detail := range settingsFieldDetailLines(f, innerWidth-2, envVar, fileValue, runningValue) {
			rightLines = append(rightLines, settingsListLine{text: "    " + detail})
		}
	}
	rightLines = fitLines(rightLines, contentRows)

	lines := make([]string, 0, height)
	lines = append(lines, m.settingsLeftTopLine(leftWidth, "Categories", leftFocused)+m.settingsRightTopLine(rightWidth, title, rightFocused))
	for i := 0; i < contentRows; i++ {
		lines = append(lines, m.settingsLeftContentLine(leftWidth, leftLines[i], leftFocused)+m.settingsRightContentLine(rightWidth, rightLines[i], rightFocused))
	}
	lines = append(lines, m.settingsLeftBottomLine(leftWidth, leftFocused)+m.settingsRightBottomLine(rightWidth, rightFocused))
	lines = append(lines, m.settingsFooterLine())
	return strings.Join(lines, "\n")
}

// settingsGroupsCopy is the Groups section's own stated difference from
// every other category (SPEC §11.5: "That difference is stated in the
// section itself rather than left for the user to discover"): groups
// live in state.db, not config.toml, so "n" (create) and "r" (rename)
// write to the store the moment they commit, never staged into
// m.settingsEdits and never gated by ctrl+s or esc's discard prompt --
// there is nothing for either one to act on here.
const settingsGroupsCopy = "Groups live in state.db, not config.toml. Creating or renaming a group here applies immediately: there is nothing for ctrl+s to save and nothing for esc to discard."

// settingsGroupsViewLines renders the settings takeover while the Groups
// category (task 018, R131 part 1) is selected: the left panel keeps
// showing the category list exactly like the generic path (settingsView)
// does, and the right panel shows settingsGroupsCopy's own stated-
// difference copy, one row per m.settingsGroups (marked/highlighted by
// m.settingsGroupIndex whenever the field list has focus), and -- while
// "n"/"r"'s typing sub-mode is open -- the name being typed plus (task
// 009's validateGroupName surfacing) m.settingsGroupNote inline, exactly
// where settingsEnvViewLines/settingsStringEditViewLines put their own
// typing row and note.
func (m Model) settingsGroupsViewLines(categories []settingsCategory, leftWidth, rightWidth, contentRows, height int) string {
	leftFocused := m.settingsFocus == settingsFocusCategories
	rightFocused := m.settingsFocus == settingsFocusFields

	categorySelTok := m.settingsSelectionToken(settingsFocusCategories)
	leftLines := make([]settingsListLine, len(categories))
	for i, cat := range categories {
		marker := "  "
		selected := i == m.settingsCategoryIndex
		if selected {
			marker = "> "
		}
		bg := theme.Token("")
		if selected {
			bg = categorySelTok
		}
		leftLines[i] = settingsListLine{text: m.settingsRenderRowOpen([]settingsRowSegment{{Text: marker + cat.Name, Tok: theme.Text}}), bg: bg}
	}
	leftLines = fitLines(leftLines, contentRows)

	innerWidth := rightWidth - 4
	var rightLines []settingsListLine
	addLine := func(text string, tok, bg theme.Token) {
		rightLines = append(rightLines, settingsListLine{text: m.settingsRenderRowOpen([]settingsRowSegment{{Text: text, Tok: tok}}), bg: bg})
	}
	for _, l := range wrapText(settingsGroupsCopy, innerWidth) {
		addLine(l, theme.Dimmed, "")
	}
	addLine("", theme.Text, "")

	fieldSelTok := m.settingsSelectionToken(settingsFocusFields)
	for i, g := range m.settingsGroups {
		marker := "  "
		selected := i == m.settingsGroupIndex
		if selected {
			marker = "> "
		}
		bg := theme.Token("")
		if selected {
			bg = fieldSelTok
		}
		addLine(marker+g.Name, theme.Text, bg)
	}
	if len(m.settingsGroups) == 0 {
		addLine("(no groups yet -- press n to create one)", theme.Dimmed, "")
	}

	if m.settingsGroupCreating || m.settingsGroupRenaming {
		addLine("", theme.Text, "")
		label := "New group name:  "
		if m.settingsGroupRenaming {
			label = "New name:  "
		}
		addLine(label+m.settingsGroupEditValue+settingsTextCursor, theme.Text, theme.Selection)
	}
	// task 019/R131 part 2's two-branch confirm, appended the same way the
	// create/rename typing row is above -- only ever shown for a non-empty
	// group (settingsStartGroupDelete drops an empty one immediately, no
	// prompt at all).
	if m.settingsGroupDeleteConfirming {
		addLine("", theme.Text, "")
		count := len(m.settingsGroupDeleteMembers)
		addLine(fmt.Sprintf("Delete group %q? It has %d session(s).", m.settingsGroupDeleteName, count), theme.Text, "")
		addLine("m moves them to default, dropping the group · d deletes them (opens the same confirm section 9.2's dd uses) · Esc cancels", theme.Dimmed, "")
	}
	if m.settingsGroupNote != "" {
		addLine("", theme.Text, "")
		addLine(m.settingsGroupNote, theme.Error, "")
	}

	rightLines = fitLines(rightLines, contentRows)

	lines := make([]string, 0, height)
	lines = append(lines, m.settingsLeftTopLine(leftWidth, "Categories", leftFocused)+m.settingsRightTopLine(rightWidth, "Groups", rightFocused))
	for i := 0; i < contentRows; i++ {
		lines = append(lines, m.settingsLeftContentLine(leftWidth, leftLines[i], leftFocused)+m.settingsRightContentLine(rightWidth, rightLines[i], rightFocused))
	}
	lines = append(lines, m.settingsLeftBottomLine(leftWidth, leftFocused)+m.settingsRightBottomLine(rightWidth, rightFocused))
	lines = append(lines, m.settingsFooterLine())
	return strings.Join(lines, "\n")
}

// settingsWrapVerbatim breaks s into rows of at most width DISPLAY COLUMNS
// (stringWidth, the same measure wrapText and padTrunc use, so a wide rune
// counts as the two cells it actually occupies) without altering a single
// byte of s: no word boundaries, no whitespace collapsing, nothing dropped.
// That is the whole reason it exists alongside wrapText -- text a user is
// still typing must be displayed exactly as it will be staged, and
// wrapText's strings.Fields pass rewrites internal whitespace. A width
// below 1 is treated as 1 so a pathologically narrow panel still terminates
// (one rune per row) rather than looping forever on a zero-width chunk.
func settingsWrapVerbatim(s string, width int) []string {
	if width < 1 {
		width = 1
	}
	var rows []string
	var cur strings.Builder
	curWidth := 0
	for _, r := range s {
		w := stringWidth(string(r))
		if curWidth+w > width && cur.Len() > 0 {
			rows = append(rows, cur.String())
			cur.Reset()
			curWidth = 0
		}
		cur.WriteRune(r)
		curWidth += w
	}
	if cur.Len() > 0 || len(rows) == 0 {
		rows = append(rows, cur.String())
	}
	return rows
}

// settingsSearchViewLines renders the takeover while `/`'s search box is
// active: the left panel keeps showing the category list unchanged (search
// spans every category, so no single category is "selected" while
// searching), and the right panel's title carries the typed query and its
// content becomes the flat, cross-category list settingsSearchMatches
// returns, each row prefixed with its own category name so a match from a
// category other than the one open before `/` was pressed is not mistaken
// for one of the still-shown left panel's category.
func (m Model) settingsSearchViewLines(categories []settingsCategory, leftWidth, rightWidth, contentRows, height int) string {
	// Search spans every category, so the left (category) list is never
	// the one up/down moves within -- it stays unfocused (`border`) for
	// the whole duration of search, and the right (results) panel, which
	// up/down does move within, carries the focus cue (`border_focus`).
	const leftFocused, rightFocused = false, true

	leftLines := make([]settingsListLine, len(categories))
	for i, cat := range categories {
		leftLines[i] = settingsListLine{text: m.settingsRenderRowOpen([]settingsRowSegment{{Text: "  " + cat.Name, Tok: theme.Text}})}
	}
	leftLines = fitLines(leftLines, contentRows)

	results := settingsSearchMatches(m.settingsSearchQuery)
	rightLines := make([]settingsListLine, len(results))
	for i, r := range results {
		marker := "  "
		selected := i == m.settingsSearchIndex
		if selected {
			marker = "> "
		}
		segs := []settingsRowSegment{
			{Text: marker + categories[r.CategoryIndex].Name + ": ", Tok: theme.Text},
			{Text: settingsFieldLabel(r.Field), Tok: theme.Hint},
		}
		bg := theme.Token("")
		if selected {
			bg = theme.Selection
		}
		rightLines[i] = settingsListLine{text: m.settingsRenderRowOpen(segs), bg: bg}
	}
	rightLines = fitLines(rightLines, contentRows)

	title := "Search: " + m.settingsSearchQuery
	lines := make([]string, 0, height)
	lines = append(lines, m.settingsLeftTopLine(leftWidth, "Categories", leftFocused)+m.settingsRightTopLine(rightWidth, title, rightFocused))
	for i := 0; i < contentRows; i++ {
		lines = append(lines, m.settingsLeftContentLine(leftWidth, leftLines[i], leftFocused)+m.settingsRightContentLine(rightWidth, rightLines[i], rightFocused))
	}
	lines = append(lines, m.settingsLeftBottomLine(leftWidth, leftFocused)+m.settingsRightBottomLine(rightWidth, rightFocused))
	lines = append(lines, m.settingsFooterLine())
	return strings.Join(lines, "\n")
}
